        ["head_mask"] = "ffffffff00ffffff00000000ffffffffffff00000000ffffff",
        ["kind"] = "judge",
        ["module"] = "game",
    },
    ["stratagem_arrow_press"] = {
        ["_"] = "(입력 부품) - 입력 틱 0xa8ee93 이 넘기는 꼴. 이 창 선수 표의 방향 누름 바이트로 방향 하나를 골라 손 모션 · 소리 · 칸 한 자 · 대조 · 원격 알림을 하고, 누름이 없으면 바로 돌아온다(0xa90ac9)",
        ["at"] = "stratagem_arrow_press",
        ["ctype"] = "void (*)(uintptr_t)",
        ["head"] = "40535556574154415541564883ec408b4128",
        ["head_at"] = 0,
        ["head_mask"] = "ffffffffffffffffffffffffffffffffff00",
        ["kind"] = "judge",
        ["module"] = "game",
    },
    ["stratagem_code_of"] = {
