modules["entry"] = function(require)
local Memory = require("native.access")
local Native = require("native.channel")
local Product = require("product")
local Runtime = require("core.runtime")
local Addons = require("core.addons")
local data = require("game.data")
local File = require("core.settings_file")
local Entry = {}
local RESOLVE_BUDGET = 2000
local RETIRED = { "hd2_hud_sites.txt", "hd2_hud_status.txt" }
local function remembered(directory)
    if directory == nil then
        return nil
    end
    local path = directory .. "/hd2_hud_resolved.txt"
    return {
        read = function()
            local file = io.open(path, "rb")
            if file == nil then
                return nil
            end
            local text = file:read("*a")
            file:close()
            return text
        end,
        write = function(text)
            local save = Native.save()
            if save ~= nil then
                save(path, text)
            end
        end,
    }
end
local Waiting = {}
Waiting.__index = Waiting
function Waiting:step(...)
    if self.done then
        return
    end
    local finished, okay, why, report = self.access.read:resolve(RESOLVE_BUDGET)
    if not finished then
        return
    end
    self.done = true
    if self.report_event ~= nil then
        self.report_event({
            event = "resolve",
            action = okay and "scanned" or why,
            us = report and report.spent and math.floor(report.spent) or nil,
            frames = report and report.slices or nil,
        })
    end
    if not okay then
        return
    end
    self.successor = self.build()
    return self.successor:step(...)
end
function Waiting:after() end
function Waiting:close()
    if self.successor ~= nil then
        return self.successor:close()
    end
end
function Entry.create(report_event, parts)
    local directory = os.getenv("APPDATA")
    local access = Memory.open(data, nil, { clock = Native.clock(), remember = remembered(directory) })
    local function build()
        local ready, _, report = access.read:status()
        local graph =
            { uses = data.uses, requires = data.requires, missing = ready and report and report.missing or nil }
        local product =
            Product.new(access, data.numbers, nil, report_event, Addons.load(report_event, nil, parts), graph)
        if directory ~= nil then
            File.bind(product.settings, directory .. "/hd2_hud_widgets.cfg")
        end
        return product
    end
    local _, why = access.read:status()
    if why == "resolving" then
        return setmetatable({ access = access, build = build, report_event = report_event }, Waiting), access
    end
    return build(), access
end
function Entry.start(environment, report_event, report)
    local directory = os.getenv("APPDATA")
    if directory ~= nil then
        for _, name in ipairs(RETIRED) do
            pcall(os.remove, directory .. "/" .. name)
        end
    end
    local program = Entry.create(report_event)
    return Runtime.new(program, report):install(environment)
end
return Entry
end
modules["features.attack"] = function(require)
local Eagles = require("game.eagles")
local Attackers = require("game.attackers")
local Shells = require("game.shells")
local Flight = require("game.flight")
local Feature = {}
Feature.__index = Feature
function Feature.new(weapon, panel, trajectory, delivery)
    local n, numbers = weapon.n, {}
    for role, name in pairs({
        kind_count = "explosion_kind_count",
        explosion_stride = "explosion_info_stride",
        radius_inner = "explosion_radius_inner",
        radius_outer = "explosion_radius_outer",
        children = "area_children",
        info_stride = "projectile_info_stride",
        info_impact = "projectile_explosion_impact",
        info_expire = "projectile_explosion_expire",
        weapon_type = "projectile_type",
        mode_at = "eagle_mode_at",
        pattern_at = "eagle_pattern_at",
        projectile_at = "eagle_projectile",
        guide_length = "guide_length",
        pattern_mode = "eagle_pattern_bomb_mode",
        strafing_mode = "eagle_strafing_mode",
        degrees = "eagle_degrees",
        pattern_count = "eagle_pattern_count",
        pattern_points = "eagle_pattern_points",
        point_stride = "eagle_pattern_point_stride",
        pattern_stride = "eagle_pattern_stride",
        bomb_projectile = "bombardment_preview_projectile",
        scatter = "bombardment_preview_spread",
        drift = "area_drift",
        shots = "guide_shots",
        salvos = "guide_salvos",
        shot_interval = "guide_shot_interval",
        salvo_interval = "guide_salvo_interval",
        turn = "guide_heading",
        centered = "guide_centered",
    }) do
        numbers[role] = n[name]
    end
    return setmetatable({
        weapon = weapon,
        panel = panel,
        trajectory = trajectory,
        delivery = delivery,
        eagles = Eagles.new(weapon, numbers),
        attackers = Attackers.new(weapon),
        shells = Shells.new(weapon, trajectory),
        numbers = numbers,
        rows = {},
    }, Feature)
end
function Feature:prepare(enabled, inputs)
    if not enabled or not self.panel.ready or inputs.world == nil then
        if self.world ~= nil then
            self:close()
        end
        return false
    end
    if self.world ~= inputs.world then
        self.eagles:clear()
        self.attackers:clear()
        self.shells:clear()
        self.next_at = nil
    end
    self.world = inputs.world
    return self.delivery.entry ~= nil
end
function Feature:observe(mode, dt)
    if self.world == nil then
        return
    end
    self.time = (self.time or 0) + (dt or 0)
    if dt == nil or self.next_at == nil or self.time >= self.next_at or self.mode ~= mode then
        self.eagles:observe(mode)
        self.attackers:observe(self.eagles.keys)
        self.shells:observe(self.attackers.keys, mode, self.world)
        self.next_at = (self.next_at or self.time) + 1 / 30
        if self.next_at <= self.time then
            self.next_at = self.time + 1 / 30
        end
    end
    self.mode = mode
end
function Feature:step(inputs, heading)
    if self.world == nil then
        return
    end
    local weapon, delivery, trajectory = self.weapon, self.delivery, self.trajectory
    local flight, scale, row = trajectory.flight, delivery.scale, nil
    if delivery.entry ~= nil and flight ~= nil and flight.finish ~= nil and scale ~= nil then
        local n = weapon.n
        row = Flight.blast(weapon.read, {
            at = flight,
            explosions = weapon.game + n.explosion_info_table,
            scale_outer = scale.outer,
            scale_inner = scale.inner,
            infos = weapon.game + n.projectile_info_table,
            eagle = delivery.eagle,
            entry_degrees = delivery.degrees,
            bombardment = delivery.bombardment,
            weapon = delivery.weapon_blob,
            patterns = weapon.game + n.eagle_pattern_table,
            heading_degrees = heading,
        }, self.numbers)
        if row ~= nil then
            row.key, row.at = "guide", flight.finish
        end
    end
    local rows = self.rows
    for index = #rows, 1, -1 do
        rows[index] = nil
    end
    if row ~= nil then
        rows[1] = row
    end
    for _, eagle in ipairs(self.eagles.rows) do
        rows[#rows + 1] = eagle
    end
    for _, shell in ipairs(self.shells.rows) do
        rows[#rows + 1] = shell
    end
    if #rows > 0 then
        trajectory:locate(inputs)
    end
end
function Feature:close()
    self.eagles:clear()
    self.attackers:clear()
    self.shells:clear()
    self.world, self.rows, self.time, self.next_at, self.mode = nil, {}, nil, nil, nil
end
return Feature
end
modules["features.body"] = function(require)
local Gauge = require("game.gauge")
local Wake = require("game.wake")
local Body = {}
Body.__index = Body
local WHITE = { 1, 1, 1 }
function Body.new(ui, panel)
    local one = ui.read:value(ui.read:module("game") + ui.n.fire_speed_unit, "f32")
    return setmetatable({
        ui = ui,
        panel = panel,
        health = Gauge.new(ui, false, -1),
        stamina = Gauge.new(ui, true, -1),
        one = one,
        health_wake = Wake.new(1),
        stamina_wake = Wake.new(0),
        events = {},
    }, Body)
end
function Body:observe(values, ready, clock, sample, map)
    self.health_on, self.stamina_on = values["hud.weapon3d.health"] == 1, values["hud.weapon3d.stamina"] == 1
    if not self.health_on then
        self.health:close()
    end
    if not self.stamina_on then
        self.stamina:close()
    end
    self.enabled = self.health_on or self.stamina_on
    local health, danger, stamina
    if self.enabled and ready then
        if self.health_on then
            health, danger = sample.health, sample.danger
        end
        if self.stamina_on then
            stamina = sample.stamina
        end
    else
        clock = nil
    end
    local v, hold = self.events, values["hud.world3d.fire_time"]
    v[1] = health
    self.health_awake = self.health_wake:step(clock, v, health ~= nil and (danger == true or map == true), hold)
    self.stamina_awake =
        self.stamina_wake:step(clock, v, stamina ~= nil and self.one ~= nil and stamina < self.one, hold)
    self.level, self.energy = health, stamina
    return self.enabled
end
local function prepare(gauge, ui, parent, layout, angle)
    local alive = ui:alive(gauge.root)
    if alive == nil then
        return false
    end
    if gauge.parent ~= parent or not alive then
        gauge:close()
        gauge:create(parent)
    end
    gauge:shape(layout, angle)
    return true
end
function Body:put(parent, values, fixed, spot, size, keep, pixel)
    local ui, panel, health, stamina = self.ui, self.panel, self.health, self.stamina
    local layout, angle = values["hud.weapon3d.layout"], values["hud.weapon3d.gauge_angle"]
    local idle, full, gap = values["hud.world3d.idle"], values["hud.weapon3d.opacity"], values["hud.weapon3d.gauge_gap"]
    local seconds, lit = ui.n.widget_fade_seconds[1], false
    if self.health_on and prepare(health, ui, parent, layout, angle) then
        if self.health_awake or not health.filled then
            health:put(self.level, panel:health_colour())
        end
        health:place(fixed, spot, size, gap, keep, pixel)
        lit = health:display(self.health_awake, idle, full, seconds) or lit
    end
    if self.stamina_on and prepare(stamina, ui, parent, layout, angle) then
        if self.stamina_awake or not stamina.filled then
            stamina:put(self.energy, WHITE)
        end
        stamina:place(fixed, spot, size, gap, keep, pixel)
        lit = stamina:display(self.stamina_awake, idle, full, seconds) or lit
    end
    return lit
end
function Body:hide()
    self.health:hide()
    self.stamina:hide()
end
function Body:close()
    self.health:close()
    self.stamina:close()
    self.health_wake:clear()
    self.stamina_wake:clear()
end
return Body
end
modules["features.call_colour"] = function(require)
local Comms = require("game.comms_inputs")
local Colour = {}
Colour.__index = Colour
function Colour.new(ui, weapon, comms)
    local judge = weapon.judge
    local self = setmetatable(
        { ui = ui, weapon = weapon, comms = comms, pending = {}, painted = {}, rgba = assert(judge:buffer("float", 4)) },
        Colour
    )
    for _, name in ipairs({ "player_of_avatar", "player_record", "player_colour" }) do
        self[name] = assert(judge:routine(name))
    end
    return self
end
function Colour:colour_of(owner)
    local w = self.weapon
    local judge, read, n = w.judge, w.read, w.n
    local players = w:manager(n.roots_player_manager_rva)
    if players == nil or judge:call(self.player_of_avatar, players, w.out, owner) == nil then
        return nil
    end
    local player = tonumber(w.out[0])
    if player == nil or player == w.invalid_local then
        return nil
    end
    local record = judge:call(self.player_record, 0, player)
    if record == nil or record == 0 then
        return nil
    end
    local key = read:value(record, "key64")
    if not key or key == w:local_key(players) then
        return nil
    end
    if judge:call(self.player_colour, 0, self.rgba, judge:uint64_of(key)) == nil then
        return nil
    end
    return self.rgba[1], self.rgba[2], self.rgba[3]
end
function Colour:paint(ring, first, last, k)
    local w, ui = self.weapon, self.ui
    local read, n = w.read, w.n
    local size = n.comms_ring_mask + 1
    if (k - first) % size >= (last - first) % size then
        return true
    end
    local at = ring + n.comms_at + k * n.comms_stride
    if read:value(at + n.comms_kind, "u32") ~= n.comms_call_kind then
        return true
    end
    local fresh = Comms.fresh(read, n, at)
    if fresh == nil then
        return true
    end
    if fresh ~= 0 then
        return false
    end
    local elapsed, lifetime = read:value(at + n.comms_elapsed, "f32"), read:value(at + n.comms_lifetime, "f32")
    if elapsed == nil or lifetime == nil or not (elapsed < lifetime) then
        return true
    end
    local owner = read:value(at + n.comms_owner, "u32")
    local red, green, blue
    if owner ~= nil then
        red, green, blue = self:colour_of(owner)
    end
    if red == nil then
        return true
    end
    Comms.brackets(ui, n, ring, at, true, red, green, blue)
    self.painted[at] = ring
    return true
end
function Colour:close()
    local w, ui = self.weapon, self.ui
    local read, n = w.read, w.n
    for at, ring in pairs(self.painted) do
        if read:value(at + n.comms_kind, "u32") == n.comms_call_kind and Comms.fresh(read, n, at) == 0 then
            Comms.brackets(ui, n, ring, at, false)
        end
    end
    self:forget()
end
function Colour:forget()
    self.ring, self.seen, self.pending, self.painted = nil, nil, {}, {}
end
function Colour:held()
    return next(self.painted) ~= nil
end
function Colour:step(enabled, editable)
    if not editable then
        self:forget()
        return
    end
    if not enabled then
        if self:held() or self.seen ~= nil then
            self:close()
        end
        return
    end
    local ring, first, last = self.comms:head()
    if ring == nil then
        return
    end
    if ring ~= self.ring then
        self:forget()
        self.ring = ring
    end
    local n = self.weapon.n
    local size = n.comms_ring_mask + 1
    local k = self.seen
    if k == nil then
        k = first
    end
    while k ~= last do
        self.painted[ring + n.comms_at + k * n.comms_stride] = nil
        self.pending[#self.pending + 1] = k
        k = (k + 1) % size
    end
    self.seen = last
    if #self.pending == 0 then
        return
    end
    local pending, kept = self.pending, 0
    for _, row in ipairs(pending) do
        if not self:paint(ring, first, last, row) then
            kept = kept + 1
            pending[kept] = row
        end
    end
    for index = #pending, kept + 1, -1 do
        pending[index] = nil
    end
end
return Colour
end
modules["features.corpse"] = function(require)
local Feature = {}
Feature.__index = Feature
local function say(report, result)
    if result ~= nil then
        report({ event = "write", id = "mark", action = result })
    end
end
function Feature.new(comms, weapon, report)
    local self = setmetatable({ comms = comms, weapon = weapon, rows = {}, report = report }, Feature)
    for _, name in ipairs({ "unit_node", "unit_world_position" }) do
        self[name] = assert(weapon.judge:routine(name))
    end
    return self
end
function Feature:point(avatar)
    local w, n = self.weapon, self.weapon.n
    local record = w:record(avatar)
    local unit
    if record ~= nil then
        unit = w.read:value(record + n.record_engine_unit, "u32")
    end
    if unit == nil or unit <= 0 then
        return nil
    end
    local node = w.judge:call(self.unit_node, unit, n.avatar_head_node)
    if node == nil or node <= 0 then
        return nil
    end
    local at = w.judge:call(self.unit_world_position, unit, node)
    if at ~= nil and at ~= 0 then
        return w.read:vector(at, 3)
    end
end
function Feature:pending()
    for _, row in ipairs(self.rows) do
        if row.deadline == nil then
            return true
        end
    end
    return false
end
function Feature:step(enabled, in_mission, avatar, players, dead, landed)
    local w, n, comms = self.weapon, self.weapon.n, self.comms
    if not enabled or not in_mission or avatar == nil then
        dead, landed = nil, nil
    end
    if dead ~= false then
        landed = nil
    end
    self:advance(enabled, in_mission, dead, landed)
    if enabled and dead == true and not self.spent then
        local ring = w:manager(n.comms_global)
        local sender
        if players ~= nil then
            sender = w:local_key(players)
        end
        local point = self:point(avatar)
        if ring ~= nil and type(sender) == "string" and point ~= nil then
            local placed, word = comms:place(ring, sender, n.quiet_mark_kind, point)
            if word == "refused" then
                if not self.refused then
                    self.refused = true
                    say(self.report, word)
                end
            elseif placed ~= nil or word ~= nil then
                self.spent = true
                if placed ~= nil then
                    word = comms:set(placed, { label = n.dead_label, picture = n.seat_skull_picture })
                    if word == "written" or word == "already" then
                        self.rows[#self.rows + 1] = placed
                        word = "placed"
                    end
                end
                say(self.report, word)
            end
        end
    end
end
function Feature:advance(enabled, in_mission, dead, landed)
    if dead ~= true then
        self.spent, self.refused = nil, nil
    end
    local kept, comms = 0, self.comms
    for _, row in ipairs(self.rows) do
        local word, keep = nil, true
        if not enabled or in_mission == false then
            word, keep = comms:take(row, in_mission == false and "left" or "taken"), false
        elseif row.deadline == nil and landed == true then
            local deadline
            word, deadline = comms:set(row, { seconds = 15 })
            if deadline == nil then
                row.deadline = false
            else
                row.deadline, word = deadline, "timed"
            end
            keep = word ~= "gone"
        elseif type(row.deadline) == "number" and dead ~= true then
            if comms:float(row, "elapsed") >= row.deadline then
                keep = false
            elseif comms:float(row, "distance") <= 5 then
                word, keep = comms:take(row, "reached"), false
            end
        end
        say(self.report, word)
        if keep then
            kept = kept + 1
            self.rows[kept] = row
        end
    end
    for i = #self.rows, kept + 1, -1 do
        self.rows[i] = nil
    end
end
function Feature:close()
    self:advance(false, false)
end
return Feature
end
modules["features.kill_pulse"] = function(require)
local Feature = {}
Feature.__index = Feature
function Feature.new(ui, panel)
    return setmetatable({ ui = ui, panel = panel }, Feature)
end
function Feature:step(enabled)
    local panel, ui = self.panel, self.ui
    if not enabled or not panel.ready then
        self.last = nil
        return
    end
    local n, read = ui.n, ui.read
    local base = panel.mission + n.hud_widgets_panels_crosshair_at
    if read:value(base + n.crosshair_hit_kind, "i32") ~= n.crosshair_hit_kill_kind then
        self.last = nil
        return
    end
    local clock = read:value(base + n.crosshair_hit_clock, "f32")
    if clock == nil then
        self.last = nil
        return
    end
    local last = self.last
    self.last = clock
    if last ~= nil and clock <= last then
        return
    end
    local at = base + n.crosshair_fixed_at
    ui:slide_scale(at, 1, 1.6, 0)
    ui:slide_scale(at, 1.6, 1, clock)
end
function Feature:close()
    self.last = nil
end
return Feature
end
modules["features.menu"] = function(require)
local Rows = require("game.menu_rows")
local Menu = {}
Menu.__index = Menu
function Menu.new(ui, settings, report, parts)
    local data = require("game.menu_data")
    local texts = { { template = data.template, resource = data.resource } }
    for _, part in ipairs(parts or {}) do
        texts[#texts + 1] = part.menu
    end
    return setmetatable({
        ui = ui,
        read = ui.read,
        n = ui.n,
        data = data,
        rows = Rows.new(ui, settings, data),
        texts_data = texts,
        labels = {},
        report = report,
    }, Menu)
end
function Menu:observe()
    local n, read = self.n, self.read
    local game = read:module("game")
    if game == nil then
        return nil, "waiting"
    end
    local state = read:ptr(game + n.menu_ui_state)
    if state == nil then
        return nil, "closed"
    end
    local count = read:value(state + n.menu_stack_count, "u32")
    if count == nil or count > (n.menu_stack_count - n.menu_stack) / 4 then
        return nil, "unread"
    end
    local found = false
    for i = 0, count - 1 do
        if read:value(state + n.menu_stack + i * 4, "u32") == n.menu_escape_type then
            found = true
        end
    end
    if not found then
        return nil, "closed"
    end
    local system = read:ptr(game + n.menu_system)
    local screen
    if system ~= nil then
        screen = read:ptr(system + n.menu_escape_screen)
    end
    if screen == nil then
        return nil, "unread"
    end
    if read:value(state + n.menu_stack + (count - 1) * 4, "u32") ~= n.menu_escape_type then
        return screen, "covered"
    end
    local language = read:ptr(game + n.ui_language_manager)
    if language == nil or read:value(language + n.ui_language_switch, "u8") ~= 0 then
        return screen, "language"
    end
    return screen, "open"
end
function Menu:forget()
    self.rows:forget()
    self.slot, self.selected = false, nil
end
function Menu:track()
    local screen, state = self:observe()
    self.outermost = state == "open"
    if state == "closed" or (screen ~= nil and screen ~= self.screen) then
        self:forget()
        self.screen = screen
    end
    return state == "open"
end
function Menu:before()
    if not self:track() or not self.slot then
        return
    end
    local n, ui, read, rows = self.n, self.ui, self.read, self.rows
    local bar = self.screen + n.menu_tab_bar
    if not rows:label_is(bar + n.menu_tab_text + n.menu_tab_stride * self.slot, self.data.tab) then
        self:forget()
        return
    end
    local current = read:value(bar + n.menu_tab_current, "u32")
    if self.selected and current == n.menu_options_tab then
        current = self.slot
    end
    if rows.content ~= nil and current ~= self.slot then
        rows:close()
    end
    self.selected = current == self.slot
    if self.selected then
        if rows.content == nil then
            ui:call("menu_tab_switch", self.screen, n.menu_options_tab)
        end
        ui:put(bar + n.menu_tab_current, n.menu_options_tab)
    end
    if read:value(bar + n.menu_tab_count, "u32") == self.slot + 1 then
        ui:put(bar + n.menu_tab_count, self.slot)
    end
end
function Menu:texts()
    for _, text in ipairs(self.texts_data) do
        local found = self.ui:call("strings_find", text.template, 0)
        local state = found ~= nil and found ~= 0 and self.read:value(found, "u8") ~= 0 and "found" or nil
        if state == nil and (text.state == nil or text.state == "found") then
            state = self.ui:call("strings_add", self.ui:resource(text.resource)) ~= 0 and "added" or "refused"
        elseif state == nil then
            state = text.state == "added" and "unresolved" or text.state
        end
        text.state = state
    end
end
function Menu:place()
    local n, ui, read, rows = self.n, self.ui, self.read, self.rows
    local bar = self.screen + n.menu_tab_bar
    if self.slot ~= nil and not rows:label_is(bar + n.menu_tab_text + n.menu_tab_stride * self.slot, self.data.tab) then
        self.slot = nil
    end
    local count, current = read:value(bar + n.menu_tab_count, "u32"), read:value(bar + n.menu_tab_current, "u32")
    if self.slot ~= nil then
        if count == self.slot then
            ui:put(bar + n.menu_tab_count, self.slot + 1)
        end
        return read:value(bar + n.menu_tab_count, "u32") == self.slot + 1
    end
    if
        count == nil
        or count < n.menu_native_tabs
        or current == nil
        or current >= count
        or count + 1 > n.menu_max_tabs
    then
        return false
    end
    for i = 0, n.menu_native_tabs - 1 do
        if
            read:value(bar + n.menu_tab_labels + i * 4, "u32")
            ~= read:value(read:module("game") + n.menu_tab_label_table + i * 4, "u32")
        then
            return false
        end
    end
    local bytes = assert(read:text(bar + n.menu_tab_labels, count * 4))
    if self.labels[bytes] == nil then
        self.labels[bytes] = assert(ui.port:own(bytes .. self.read.bytes.pack(self.data.tab, 4)))
    end
    ui:call("menu_tabs_set", bar, self.labels[bytes], count + 1)
    ui:call("menu_tab_select", bar, current, 0, 0)
    rows:label(bar + n.menu_tab_text + n.menu_tab_stride * count, self.data.tab)
    self.slot = count
    return true
end
function Menu:after(dt, completed)
    if not self:track() then
        return
    end
    self:texts()
    if self.slot == false then
        self.slot = nil
        return
    end
    if not self:place() then
        if self.rows.content ~= nil then
            self.rows:close()
        end
        return
    end
    local bar = self.screen + self.n.menu_tab_bar
    local current = self.read:value(bar + self.n.menu_tab_current, "u32")
    if self.selected and current == self.n.menu_options_tab then
        self.ui:put(bar + self.n.menu_tab_current, self.slot)
        current = self.slot
    end
    self.selected = nil
    if completed ~= false and current == self.slot then
        if self.rows.content == nil then
            self.rows:open(self.screen)
        end
        self.rows:step(dt or 0, self.report)
    end
end
function Menu:close()
    local screen, state = self:observe()
    if screen == self.screen and state ~= "closed" and screen ~= nil then
        self.rows:close()
        local bar = screen + self.n.menu_tab_bar
        if
            self.slot
            and self.rows:label_is(bar + self.n.menu_tab_text + self.n.menu_tab_stride * self.slot, self.data.tab)
        then
            if self.read:value(bar + self.n.menu_tab_current, "u32") == self.slot then
                self.ui:put(bar + self.n.menu_tab_current, self.n.menu_options_tab)
            end
            if self.read:value(bar + self.n.menu_tab_count, "u32") == self.slot + 1 then
                self.ui:put(bar + self.n.menu_tab_count, self.slot)
            end
        end
    end
    self:forget()
    self.outermost = false
end
return Menu
end
modules["features.pack"] = function(require)
local Pack = require("game.pack")
local Gauge = require("game.gauge")
local Wake = require("game.wake")
local Feature = {}
Feature.__index = Feature
local WHITE = { 1, 1, 1 }
function Feature.new(ui, weapon)
    return setmetatable(
        { ui = ui, values = Pack.new(weapon), gauge = Gauge.new(ui, true, 1), wake = Wake.new(1), events = {} },
        Feature
    )
end
function Feature:observe(enabled, clock, worn, gauge, hold, keep, wield)
    self.enabled, self.worn, self.wield = enabled, worn, wield
    if not enabled or clock == nil then
        self.wake:clear()
        self.awake = nil
        if not enabled then
            self.gauge:close()
        end
        return
    end
    self.events[1] = gauge
    self.awake = self.wake:step(clock, self.events, self.values.busy == true or keep == true, hold)
end
function Feature:put(parent, values, fixed, spot, size, keep, pixel)
    if not self.enabled then
        return false
    end
    local ui, gauge = self.ui, self.gauge
    if not self.worn or self.values:hides(self.wield) then
        gauge:hide()
        return false
    end
    local alive = ui:alive(gauge.root)
    if alive == nil then
        return false
    end
    if gauge.parent ~= parent or not alive then
        gauge:close()
        gauge:create(parent)
    end
    gauge:shape(values["hud.weapon3d.layout"], values["hud.weapon3d.gauge_angle"])
    if self.awake or not gauge.filled then
        local share = self.values.share
        if share == nil and self.values.left ~= nil then
            share = 1 - self.values.left
        end
        gauge:put(share, WHITE)
        self.has_value = share ~= nil
    end
    if not self.has_value then
        gauge:hide()
        return false
    end
    gauge:place(fixed, spot, size, values["hud.weapon3d.gauge_gap"], keep, pixel)
    return gauge:display(
        self.awake,
        values["hud.world3d.idle"],
        values["hud.weapon3d.opacity"],
        ui.n.widget_fade_seconds[1]
    )
end
function Feature:hide()
    self.gauge:hide()
end
function Feature:close()
    self.gauge:close()
    self.wake:clear()
    self.awake = nil
end
return Feature
end
modules["features.reinforce"] = function(require)
local Inputs, Marks = require("game.reinforcement"), require("game.comms_marks")
local Feature = {}
Feature.__index = Feature
function Feature.new(comms, weapon, report)
    return setmetatable({
        weapon = weapon,
        inputs = Inputs.new(weapon),
        callers = Marks.new(comms, weapon.n.enemy_ping_sound, report),
        spots = Marks.new(comms, nil, report),
        time = 0,
    }, Feature)
end
function Feature:step(enabled, panel, players)
    if not enabled or panel.in_mission == false then
        self:close(panel.in_mission == false)
        return
    end
    if panel.in_mission ~= true then
        return
    end
    local dt = panel.dt
    self.time = self.time + (dt or 0)
    local callers_due = dt == nil or self.call_at == nil or self.time >= self.call_at
    local spots_due = dt == nil or self.spot_at == nil or self.time >= self.spot_at
    if not callers_due and not spots_due then
        return
    end
    local w, n, input = self.weapon, self.weapon.n, self.inputs
    input:observe(callers_due, spots_due)
    local ring, sender, terrain
    if (callers_due and #input.callers > 0) or (spots_due and #input.spots > 0) then
        input:labels()
        ring, terrain = w:manager(n.comms_global), w:manager(n.ground_world)
        sender = w:local_key(players)
    end
    if callers_due then
        self.callers:update(input.callers, ring, sender, input.call_label, input.picture, terrain)
        self.call_at = self.time + 1 / 4
    end
    if spots_due then
        self.spots:update(input.spots, ring, sender, input.label, input.picture, terrain)
        self.spot_at = self.time + 1 / 30
    end
end
function Feature:close(left)
    self.callers:update(nil, nil, nil, nil, nil, nil, left)
    self.spots:update(nil, nil, nil, nil, nil, nil, left)
    self.inputs:clear()
    self.time, self.call_at, self.spot_at = 0, nil, nil
end
return Feature
end
modules["features.reticle"] = function(require)
local Reticle = {}
Reticle.__index = Reticle
local function unique(rows, field, value, second, other)
    local found
    for _, row in ipairs(rows) do
        if row[field] == value and (second == nil or row[second] == other) then
            if found ~= nil then
                return nil
            end
            found = row
        end
    end
    return found
end
function Reticle.new(access, n)
    return setmetatable(
        { read = access.read, judge = access.call.judge, write = access.write, n = n, third = {}, first = {} },
        Reticle
    )
end
function Reticle:tables()
    local read, n = self.read, self.n
    local game = read:module("game")
    if game == nil then
        return
    end
    local owner = read:ptr(game + n.roots_entity_owner_rva)
    if owner == nil then
        return
    end
    local book = read:ptr(owner + n.weapon_data_registry_table)
    if book == nil then
        return
    end
    local rows = {}
    for i = 0, n.crosshair_count - 1 do
        local at = game + n.crosshair_table + i * n.crosshair_stride
        rows[#rows + 1] = {
            key = read:value(at + n.crosshair_key),
            mode = read:value(at + n.crosshair_mode),
            flags = read:value(at + n.crosshair_flags),
        }
    end
    if #rows == 0 then
        return
    end
    return owner, book, rows
end
function Reticle:third_target(book, rules)
    local read, n = self.read, self.n
    local hidden = unique(rules, "mode", n.crosshair_hidden_mode)
    if hidden == nil then
        return nil, "rule-not-one"
    end
    local found
    for i = 0, n.weapon_data_registry_last do
        local slot = book + i * n.registry_slot_stride
        if read:value(slot, "hex64") ~= nil then
            local row = book
                + n.weapon_data_registry_head
                + read:value(slot + n.registry_slot_row) * n.weapon_data_registry_size
            local at = row + n.crosshair_type
            local current = read:value(at)
            if current == hidden.key then
                if found ~= nil then
                    return nil, "target-not-one"
                end
                found = { at = at, row = row, from = current, to = rules[1].key }
            end
        end
    end
    if found == nil then
        return nil, "target-not-one"
    end
    return { found }
end
function Reticle:first_targets(owner, rules)
    local read, n, judge = self.read, self.n, self.judge
    local links = read:ptr(owner + n.linked_ammo_registry_table)
    if links == nil then
        return nil, "wait"
    end
    local call = judge:routine("weapon_data_find")
    if call == nil then
        return nil, "spec"
    end
    local targets = {}
    for i = 0, n.linked_ammo_registry_slots - 1 do
        local key = read:value(links + i * n.linked_ammo_registry_slot_stride, "hex64")
        if key ~= nil then
            local row = judge:call(call, judge:uint64_of(key))
            if row == nil then
                return nil, "wait"
            end
            if row ~= 0 then
                local at = row + n.crosshair_type
                local from = read:value(at)
                local current, to = unique(rules, "key", from), nil
                if current ~= nil then
                    local flag, flags = n.crosshair_first_person_flag, current.flags
                    if math.floor(flags / flag) % 2 == 0 then
                        flags = flags + flag
                    end
                    local selected = unique(rules, "mode", current.mode, "flags", flags)
                    if selected ~= nil then
                        to = selected.key
                    end
                end
                targets[#targets + 1] = { at = at, row = row, key = key, from = from, to = to }
            end
        end
    end
    if #targets == 0 then
        return nil, "target-none"
    end
    return targets
end
function Reticle:apply(state, targets, why, id, say)
    if targets == nil and why == "wait" then
        return
    end
    state.settled, state.applied = true, {}
    if targets == nil then
        say({ event = "write", id = id, action = why })
        return
    end
    local read, n, pack = self.read, self.n, self.read.bytes.pack
    for _, target in ipairs(targets) do
        local result
        for i = 0, n.sight_count - 1 do
            local at = target.row + n.sight_at + i * n.sight_stride
            if read:value(at) ~= 0 or read:value(at + n.sight_value) ~= 0 then
                result = "overridden"
                break
            end
        end
        if result == nil and target.to == nil then
            result = "rule-not-one"
        end
        if result == nil then
            local _, word = self.write:swap(target.at, pack(target.from, 4), pack(target.to, 4))
            result = word
            if word == "written" then
                state.applied[#state.applied + 1] = target
            end
        end
        say({ event = "write", id = id, action = result, value = target.key })
    end
end
function Reticle:restore(state, id, say)
    if not state.settled then
        return
    end
    local pack = self.read.bytes.pack
    for _, target in ipairs(state.applied or {}) do
        local _, word = self.write:swap(target.at, pack(target.to, 4), pack(target.from, 4))
        say({ event = "write", id = id, action = word == "written" and "restored" or word, value = target.key })
    end
    state.settled, state.applied = nil, nil
end
function Reticle:step(editing, say)
    if not editing then
        self:restore(self.third, "third_person", say)
        self:restore(self.first, "first_person", say)
        return
    end
    if self.third.settled and self.first.settled then
        return
    end
    local owner, book, rules = self:tables()
    if owner == nil then
        return
    end
    if not self.third.settled then
        local targets, why = self:third_target(book, rules)
        self:apply(self.third, targets, why, "third_person", say)
    end
    if not self.first.settled then
        local targets, why = self:first_targets(owner, rules)
        self:apply(self.first, targets, why, "first_person", say)
    end
end
return Reticle
end
modules["features.squad"] = function(require)
local Inputs = require("game.squad_inputs")
local Card = require("game.stratagem_card")
local BOOSTERS = require("game.resources").boosters
local Feature = {}
Feature.__index = Feature
function Feature.new(ui, weapon, comms)
    return setmetatable({ ui = ui, inputs = Inputs.new(weapon, comms), seats = {}, frame = 0, time = 0 }, Feature)
end
local function reparent(ui, held, parent, root)
    if held.parent ~= parent then
        ui:call("widget_detach", root.at)
        ui:context(parent, function()
            ui:attach(parent, root)
        end)
        held.parent = parent
    end
end
local function close_status(ui, seat)
    ui:destroy(seat.icon)
    ui:destroy(seat.skull)
    ui:destroy(seat.root)
    seat.parent = nil
end
function Feature:vectors(node, material)
    local ui, w = self.ui, self.inputs.weapon
    local n = ui.n
    if material == n.seat_skull_picture or material == n.ping_glyph_material or material == n.mask_material then
        if self.bend == nil then
            self.bend = w.read:vector(w.game + n.picture_bend_data, 4)
        end
        if material == n.mask_material then
            if self.white == nil then
                self.white = w.read:vector(w.game + n.mask_white, 4)
            end
            if self.white ~= nil then
                ui:material_four(node, n.mask_c0, unpack(self.white))
                ui:material_four(node, n.mask_c1, unpack(self.white))
            end
            if self.bend ~= nil then
                ui:material_four(node, n.mask_c2, unpack(self.bend))
            end
        else
            if self.face == nil then
                self.face = w.read:vector(w.game + n.picture_face_data, 2)
            end
            if self.bend ~= nil then
                ui:material_four(node, n.picture_bend_key, unpack(self.bend))
            end
            if self.face ~= nil then
                ui:material_pair(node, n.picture_face_key, unpack(self.face))
            end
        end
    end
end
function Feature:status(seat, row, subject)
    local ui, n = self.ui, self.ui.n
    if row == nil or row.parent == nil then
        close_status(ui, seat)
        return
    end
    local alive = ui:alive(seat.root)
    if alive == nil then
        return
    end
    if not alive then
        close_status(ui, seat)
        seat.fresh = true
        ui:context(row.parent, function()
            seat.root = ui:frame(seat.root)
            ui:attach(row.parent, seat.root)
            ui:size(seat.root, 0, 0)
            ui:anchor(seat.root, 0, 1)
            ui:position(seat.root, subject and -8 or -18, 12)
            seat.skull = ui:image_node(seat.skull)
            seat.icon = ui:image_node(seat.icon)
            for _, node in ipairs({ seat.skull, seat.icon }) do
                ui:size(node, 36, 36)
                ui:pivot(node, 0.5, 0.5)
                ui:layer(node, n.squad_picture_layer)
                ui:attach(seat.root.at, node)
            end
        end)
        seat.parent = row.parent
    else
        reparent(ui, seat, row.parent, seat.root)
    end
    ui:show(seat.root, row.player ~= nil)
    if row.skull ~= nil then
        if seat.skull.material ~= row.skull then
            ui:material(seat.skull, row.skull)
            self:vectors(seat.skull, row.skull)
            seat.skull.material = row.skull
        end
        ui:show(seat.skull, true)
    else
        ui:show(seat.skull, false)
    end
    local texture = row.icon
    if row.booster ~= nil then
        texture = BOOSTERS[row.booster]
    end
    ui:image(seat.icon, texture, row.material or n.picture_material)
    if texture ~= nil then
        self:vectors(seat.icon, row.material)
    end
end
local function close_calls(ui, held)
    for _, card in ipairs(held.cards) do
        card:close()
    end
    ui:destroy(held.root)
    held.parent = nil
end
function Feature:calls(held, row, dt)
    local ui, n = self.ui, self.ui.n
    if row == nil or row.edge == nil then
        close_calls(ui, held)
        return
    end
    local alive = ui:alive(held.root)
    if alive == nil then
        return
    end
    if not alive then
        close_calls(ui, held)
        ui:context(row.edge, function()
            held.root = ui:frame(held.root)
            ui:size(held.root, 0, 0)
            ui:anchor(held.root, 1, 0.5)
            ui:attach(row.edge, held.root)
        end)
        held.parent = row.edge
    else
        reparent(ui, held, row.edge, held.root)
    end
    local calls = row.calls or {}
    ui:show(held.root, #calls > 0)
    for index, call in ipairs(calls) do
        local card = held.cards[index]
        if card == nil then
            card = Card.new(ui)
            held.cards[index] = card
        end
        local live = ui:alive(card.node)
        if live == false then
            ui:context(row.edge, function()
                local node = card:create(held.root.at, self.frame, n.component_card_squad_layer, false)
                ui:anchor(node, 1, 0.5)
                ui:pivot(node, 0, 0.5)
                ui:position(node, 8 + (index - 1) * 52, 0)
                ui:call("widget_opacity_set", node.at + n.stratagem_uses_widget, 0)
            end)
        end
        if live ~= nil then
            card:update(self.frame, dt, call.row, call.record, n.component_card_calling, call.beacon)
        end
    end
    for index = #calls + 1, #held.cards do
        held.cards[index]:update(self.frame, nil)
    end
end
local FILL_OPACITY = 0.3
local function close_fills(ui, fills)
    for _, fill in pairs(fills) do
        ui:destroy(fill.node)
        fill.parent = nil
    end
end
function Feature:fill(fill, cell, share, fresh)
    local ui, n = self.ui, self.ui.n
    if fresh or fill.node == nil or not fill.node.live or fill.parent ~= cell then
        local read = self.inputs.weapon.read
        local width = read:value(cell + n.widget_local_size, "f32")
        local height = read:value(cell + n.widget_local_size + 4, "f32")
        ui:destroy(fill.node)
        fill.parent = nil
        if width == nil or height == nil then
            return
        end
        ui:context(cell, function()
            local node = ui:image_node(fill.node)
            fill.node = node
            ui:image(node, n.squad_fill_texture, n.squad_fill_material)
            ui:call("widget_uv_set", node.at, ui:pair(0.5, 0.5), ui:pair(0.5, 0.5))
            local tint = n.squad_bracket_vector
            ui:colour(node, tint[2], tint[3], tint[4])
            ui:opacity(node, FILL_OPACITY)
            ui:layer(node, n.squad_cell_blur_layer)
            ui:size(node, width, height)
            ui:anchor(node, 0.5, 0)
            ui:pivot(node, 0.5, 0)
            ui:position(node, 0, 0)
            ui:attach(cell, node)
        end)
        fill.parent = cell
    end
    if share == nil or share <= 0 then
        ui:show(fill.node, false)
        return
    end
    ui:scale(fill.node, 1, share)
    ui:show(fill.node, true)
end
function Feature:step(panel, enabled, avatar, player, players, dead)
    self.frame = self.frame + 1
    local dt = panel.dt
    self.time = self.time + (dt or 0)
    local supply = enabled and (dt == nil or self.supply_at == nil or self.time >= self.supply_at)
    if supply then
        self.supply_at = self.time + 1 / 4
    elseif not enabled then
        self.supply_at = nil
    end
    self.inputs:observe(panel, enabled, supply, avatar, player, players, dead)
    local n = self.ui.n
    for i = 1, n.hud_squad_count + 1 do
        local seat = self.seats[i]
        if seat == nil then
            seat = { calls = { cards = {} }, fills = { stim = {}, ammo = {}, pack = {} } }
            self.seats[i] = seat
        end
        local subject = i > n.hud_squad_count
        local row = subject and self.inputs.view or self.inputs.rows[i]
        seat.fresh = false
        self:status(seat, row, subject)
        if not subject then
            self:calls(seat.calls, row, panel.dt)
            if row == nil then
                close_fills(self.ui, seat.fills)
                seat.pack_id, seat.shares_of = nil, nil
            else
                local pack = row.parent + n.squad_slot_base
                if
                    seat.fresh
                    or seat.shares_of ~= row.parent
                    or seat.shares_player ~= row.player
                    or seat.shares_avatar ~= row.avatar
                then
                    seat.stim, seat.ammo, seat.pack, seat.shares_of = nil, nil, nil, nil
                end
                if supply then
                    local share = row.pack
                    if row.pack_id == nil or row.pack_id ~= seat.pack_id then
                        if row.pack_id ~= nil then
                            self.ui:put(pack + n.squad_cell_share, n.squad_cell_unset, 4)
                        end
                        share = nil
                    end
                    seat.pack_id = row.pack_id
                    seat.stim, seat.ammo, seat.pack, seat.shares_of = row.stim, row.ammo, share, row.parent
                    seat.shares_player, seat.shares_avatar = row.player, row.avatar
                end
                self:fill(seat.fills.stim, row.parent + n.squad_stim_cell, seat.stim, seat.fresh)
                self:fill(seat.fills.ammo, row.parent + n.squad_weapon_object, seat.ammo, seat.fresh)
                self:fill(seat.fills.pack, pack, seat.pack, seat.fresh)
            end
        end
    end
end
function Feature:close()
    for _, seat in ipairs(self.seats) do
        close_status(self.ui, seat)
        close_calls(self.ui, seat.calls)
        if seat.fills ~= nil then
            close_fills(self.ui, seat.fills)
        end
    end
end
return Feature
end
modules["features.stratagem"] = function(require)
local List = require("game.stratagem_list")
local Card = require("game.stratagem_card")
local Inputs = require("game.stratagem_inputs")
local Stratagem = {}
Stratagem.__index = Stratagem
function Stratagem.new(ui, panel, weapon, pick)
    return setmetatable({
        ui = ui,
        panel = panel,
        inputs = Inputs.new(weapon),
        pick = pick,
        list = List.new(ui),
        card = Card.new(ui),
        off = {},
    }, Stratagem)
end
function Stratagem:vanilla(hidden)
    local panel, ui, n = self.panel, self.ui, self.ui.n
    if not panel.editable then
        self.edited = nil
        return
    end
    local group = panel.mission + n.hud_widgets_panels_stratagem_hud_at + n.stratagem_panel_group
    if self.edited ~= nil and (self.edited ~= group or not hidden) then
        if self.edited == group then
            ui:call("widget_opacity_set", group, n.widget_opacity_default[1])
        end
        self.edited = nil
    end
    if hidden and self.edited ~= group then
        ui:call("widget_opacity_set", group, 0)
        self.edited = group
    end
end
function Stratagem:prepare(enabled, world, arrow, list)
    return self.inputs:prepare(self.panel, world, enabled or arrow, list)
end
function Stratagem:observe(enabled, world, player, players, arrow, cell)
    if enabled or arrow then
        self.inputs:observe(self.panel, world, player, players, cell)
    end
    self:vanilla(enabled and self.inputs.showing == true)
    if not enabled then
        self:drop()
    elseif not self.inputs.showing then
        if self.segment and self.ui:alive(self.root) == true then
            self.list:update(nil, nil, nil, 0)
        end
        self:hide()
    end
    self.segment = enabled and self.inputs.showing == true
    self.world = world
    return self.inputs.showing
end
function Stratagem:create(parent, frame)
    local ui, n = self.ui, self.ui.n
    ui:context(parent, function()
        self.root = ui:frame(self.root)
        ui:size(self.root, 140, 90)
        ui:opacity(self.root, 0)
        ui:attach(parent, self.root)
        self.listing = ui:frame(self.listing)
        ui:size(self.listing, 140, 90)
        ui:attach(self.root.at, self.listing)
        self.list:create(self.listing.at, frame)
        local card = self.card:create(self.root.at, frame, n.stratagem_row_card_layer, true)
        ui:anchor(card, 0.5, 0.5)
        ui:pivot(card, 0.5, 0.5)
        ui:scale(card, 0.6, 0.6)
        ui:call("widget_opacity_set", card.at + n.stratagem_uses_widget, 0)
    end)
    self.parent = parent
end
function Stratagem:put(parent, frame, values)
    local ui, input = self.ui, self.inputs
    local alive = ui:alive(self.root)
    if alive == nil then
        return false
    end
    if self.parent ~= parent or not alive then
        self:drop()
        self:create(parent, frame)
    end
    ui:show(self.root, true)
    ui:position(self.listing, values["hud.stratagem3d.list_x"], values["hud.stratagem3d.list_y"])
    ui:position(self.card.node, values["hud.stratagem3d.icon_x"], values["hud.stratagem3d.icon_y"])
    ui:show(self.listing, input.listing == true)
    local pick, list, off = self.pick, self.list, self.off
    off[ui.n.sos_stratagem] = values["hud.stratagem3d.skip_sos"] == 1 or nil
    off[ui.n.eagle_rearm_stratagem] = values["hud.stratagem3d.skip_rearm"] == 1 or nil
    if next(off) == nil then
        off = nil
    end
    local wheel = pick ~= nil and values["hud.stratagem3d.pick"] == 1
    if wheel and input.listing and list.valid then
        pick:step(
            self.world,
            input.input,
            list,
            values["hud.stratagem3d.pick_gap"],
            self.panel.dt,
            off,
            values["hud.stratagem3d.pick_remember"] == 1,
            self.panel
        )
    end
    self.list:update(frame, self.panel.dt, input.player, input.mode, input.original, off, wheel)
    self.card:update(frame, self.panel.dt, input.row, input.card_record, ui.n.component_card_ready)
    ui:fade(self.root, true, ui.n.widget_fade_alpha[1], ui.n.widget_fade_seconds[1])
    return true
end
function Stratagem:hide()
    if self.root ~= nil and self.root.live then
        self.ui:opacity(self.root, 0)
        self.ui:show(self.root, false)
    end
    self.list:update(nil, nil)
    self.card:update(nil, nil)
end
function Stratagem:drop()
    self.list:close()
    self.card:close()
    self.ui:destroy(self.listing)
    self.ui:destroy(self.root)
    self.parent = nil
end
function Stratagem:close()
    self:vanilla(false)
    self:drop()
end
return Stratagem
end
modules["features.stratagem_cooldown"] = function(require)
local Card = require("game.stratagem_card")
local Gauge = require("game.gauge")
local Wake = require("game.wake")
local Feature = {}
Feature.__index = Feature
local CARD_GAP = 4
local IDLE_DIM = 0.5
function Feature.new(ui, panel, inputs)
    local n = ui.n
    local blocked = {
        [n.component_card_calling] = true,
        [n.component_card_cooling] = true,
        [n.component_card_zone0] = true,
        [n.component_card_zone1] = true,
    }
    local row_cells =
        ui.read.layout({ { n.stratagem_row_card + n.component_card_state, "u32" }, { n.stratagem_row_raised, "u8" } })
    return setmetatable({
        ui = ui,
        panel = panel,
        inputs = inputs,
        blocked = blocked,
        cards = {},
        states = {},
        raised = {},
        mission = {},
        bright = {},
        shown = {},
        root_place = {},
        scene = {},
        wake = Wake.new(1),
        row_cells = row_cells,
        row_values = {},
    }, Feature)
end
function Feature:observe(values, ready, clock, avatar, players, held)
    self.enabled = values["hud.weapon3d.cooldown"] == 1
    if not self.enabled then
        self:close()
        return false
    end
    self.avatar, self.players = avatar, players
    if not ready then
        clock = nil
    end
    self.scene[1] = held == true
    self.awake = self.wake:step(clock, self.scene, held == true, values["hud.world3d.fire_time"])
    return true
end
local function read_rows(self)
    local ui, n, states, raised = self.ui, self.ui.n, self.states, self.raised
    for row = 1, n.stratagem_list_rows do
        states[row], raised[row] = nil, nil
    end
    self.record = nil
    local record = self.inputs:history(self.avatar, self.players)
    local rows
    if record ~= nil then
        rows = ui.read:value(record + n.stratagem_record_rows, "u32")
    end
    if rows == nil then
        return
    end
    self.record, self.rows_at = record, self.inputs:wrapper(self.panel) + n.stratagem_list + n.stratagem_list_first_row
    local cells, values = self.row_cells, self.row_values
    for row = 1, math.min(rows, n.stratagem_list_rows) do
        local got = ui.read:value(self.rows_at + (row - 1) * n.stratagem_list_row_size, cells, values)
        if got ~= nil then
            states[row], raised[row] = got[1], got[2]
        end
    end
end
local function visible(self, row, idle)
    local n, state = self.ui.n, self.states[row]
    if state == nil then
        return nil
    end
    local raised, card = self.raised[row] ~= nil and self.raised[row] ~= 0, self.cards[row]
    local seen = card ~= nil and (card.valid or (card.view ~= nil and card.view.lit))
    if
        not self.blocked[state]
        and state ~= n.component_card_unavailable
        and not (state == n.component_card_ready and raised and seen)
    then
        return nil
    end
    local bright = raised or self.awake == true
    if not bright and not (idle > 0) and not seen then
        return nil
    end
    local mission = self.ui.read:value(self.record + (row - 1) * n.stratagem_row_stride + n.stratagem_row_mission, "u8")
    if mission == nil or (mission ~= 0 and state ~= n.component_card_calling) then
        return nil
    end
    return mission, bright
end
local function hide_card(card, frame)
    if card.view == nil or (not card.valid and not card.view.lit) then
        return
    end
    card:update(frame, nil)
    card.view.lit, card.place[1] = false, nil
end
function Feature:create(parent)
    local ui = self.ui
    ui:context(parent, function()
        self.root = ui:frame(self.root)
        ui:size(self.root, 0, 0)
        ui:anchor(self.root, 0.5, 0.5)
        ui:pivot(self.root, 0.5, 0.5)
        ui:opacity(self.root, 0)
        ui:attach(parent, self.root)
    end)
    self.parent, self.root_place[1], self.root_place[2] = parent, nil, nil
end
function Feature:card(row, frame, scale, bright, idle, full, seconds)
    local ui, n = self.ui, self.ui.n
    local card = self.cards[row]
    if card == nil then
        card = Card.new(ui)
        self.cards[row] = card
    end
    local alive = ui:alive(card.node)
    if alive == nil then
        return nil
    end
    if not alive then
        ui:context(self.parent, function()
            local node = card:create(self.root.at, frame, n.stratagem_row_card_layer, true)
            ui:anchor(node, 0.5, 0.5)
            ui:pivot(node, 0.5, 0.5)
        end)
        card.size, card.scale = ui.read:vector(card.node.at + n.widget_local_size, 2), nil
        card.place, card.view = card.place or {}, card.view or { ui = ui }
        card.place[1], card.view.root, card.view.lit = nil, card.node, false
        return nil
    end
    if card.size == nil then
        return nil
    end
    if not Gauge.display(card.view, bright, idle, full, seconds, IDLE_DIM) then
        hide_card(card, frame)
        return nil
    end
    if card.scale ~= scale then
        ui:scale(card.node, scale, scale)
        card.scale = scale
    end
    local state, fresh = self.states[row], not card.valid
    card:update(frame, self.panel.dt, row - 1, self.record, state)
    if fresh and card.valid and (state == n.component_card_calling or state == n.component_card_cooling) then
        Card.carry(ui, card.node.at, self.rows_at + (row - 1) * n.stratagem_list_row_size + n.stratagem_row_card)
    end
    if card.valid then
        return card
    end
end
function Feature:put(parent, frame, values, fixed, spot, size, keep, pixel)
    if not self.enabled then
        return false
    end
    local ui, n = self.ui, self.ui.n
    local alive = ui:alive(self.root)
    if alive == nil then
        return false
    end
    if self.parent ~= parent or not alive then
        self:drop()
        self:create(parent)
    end
    read_rows(self)
    local scale, gap = values["hud.weapon3d.cooldown_size"], values["hud.weapon3d.cooldown_gap"]
    local idle, full, seconds = values["hud.world3d.idle"], values["hud.weapon3d.opacity"], n.widget_fade_seconds[1]
    local mission, bright, shown, pitch, height = self.mission, self.bright, self.shown, 0, 0
    for index = #shown, 1, -1 do
        shown[index] = nil
    end
    for row = 1, n.stratagem_list_rows do
        mission[row], bright[row] = nil, nil
        if self.record ~= nil then
            mission[row], bright[row] = visible(self, row, idle)
        end
        local card = self.cards[row]
        if mission[row] == nil and card ~= nil then
            hide_card(card, frame)
        end
    end
    for pass = 1, 2 do
        for row = 1, n.stratagem_list_rows do
            if mission[row] ~= nil and (mission[row] ~= 0) == (pass == 1) then
                local card = self:card(row, frame, scale, bright[row], idle, full, seconds)
                if card ~= nil then
                    shown[#shown + 1] = card
                    pitch, height =
                        math.max(pitch, (card.size[1] + CARD_GAP) * scale), math.max(height, card.size[2] * scale)
                end
            end
        end
    end
    if #shown == 0 then
        self:hide()
        return false
    end
    ui:fade(self.root, true, 1, seconds)
    local toward = Gauge.toward(values["hud.weapon3d.layout"])
    local x, y = Gauge.centre(1, toward, fixed, spot)
    if toward[1] ~= 0 then
        y = y - size[2] / 2 - gap - height / 2
    else
        x = x + size[1] / 2 + gap + pitch * #shown / 2
    end
    Gauge.approach(ui, self.root, self.root_place, x, y, keep, pixel)
    for index, card in ipairs(shown) do
        Gauge.approach(ui, card.node, card.place, (index - (#shown + 1) / 2) * pitch, 0, keep, pixel)
    end
    return true
end
function Feature:hide()
    if self.root ~= nil and self.root.live then
        self.ui:opacity(self.root, 0)
    end
    self.root_place[1] = nil
end
function Feature:drop()
    for row, card in pairs(self.cards) do
        card:close()
        self.cards[row] = nil
    end
    self.ui:destroy(self.root)
    self.parent = nil
end
function Feature:close()
    if next(self.cards) == nil and (self.root == nil or not self.root.live) and self.wake.clock == nil then
        return
    end
    self:drop()
    self.wake:clear()
end
return Feature
end
modules["features.throw_distance"] = function(require)
local Point = require("game.screen_point")
local Feature = {}
Feature.__index = Feature
function Feature.new(ui, judge, panel, trajectory, view)
    return setmetatable(
        { ui = ui, panel = panel, trajectory = trajectory, view = view, point = Point.new(judge, ui.n) },
        Feature
    )
end
function Feature:close()
    self.ui:destroy(self.root)
    if self.label ~= nil then
        self.label.live, self.label.text, self.label.shown = false, nil, nil
    end
    self.parent = nil
end
function Feature:step(values)
    local ui, panel, source, n = self.ui, self.panel, self.trajectory, self.ui.n
    if values["hud.throw_distance"] ~= 1 or not panel.ready then
        self:close()
        return
    end
    local flight = source.flight
    local x, y, count
    if source.from_hand == true and flight ~= nil and flight.distance ~= nil then
        x, y = self.point:project(self.view.camera, flight.finish)
        count = math.floor(flight.distance)
    end
    if x == nil then
        if ui:alive(self.root) then
            ui:show(self.root, false)
        end
        return
    end
    local parent = panel.mission - n.hud_widgets_mission_hud + n.hud_marker_layer
    if self.parent ~= parent or ui:alive(self.root) ~= true then
        self:close()
        ui:context(parent, function()
            self.root = ui:frame(self.root)
            ui:size(self.root, 0, 0)
            ui:attach(parent, self.root)
            self.label = ui:label_node(
                n.ping_distance_font,
                n.world_text_flat,
                n.world_text_style,
                n.ping_distance_template,
                self.label
            )
            ui:attach(self.root.at, self.label)
            ui:anchor(self.label, 0.5, 0.5)
            ui:pivot(self.label, 0.5, 0.5)
            ui:position(self.label, 0, -30)
            ui:layer(self.label, n.ping_distance_layer)
            ui:colour(self.label, 1, 1, 1)
        end)
        self.parent = parent
    end
    ui:position(self.root, x, y)
    ui:number(self.label, n.ping_distance_count_arg, count)
    ui:show(self.root, true)
end
return Feature
end
modules["features.trajectory"] = function(require)
local Projectile = require("game.projectile")
local Launch = require("game.throw_launch")
local Flight = require("game.flight")
local Feature = {}
Feature.__index = Feature
local HOLD = 0.2
local WHITE, YELLOW, BLACK = 16777215, 255 * 65536 + 255 * 256, 0
local FOE = require("game.resources").decal.foe_colour % 16777216
function Feature.new(weapon, equipment, panel)
    local n, judge, read = weapon.n, weapon.judge, weapon.read
    local calls = {}
    for role, name in pairs({
        boost = "throw_boost_apply",
        muzzle = "muzzle_node_of",
        position = "unit_world_position",
        velocity = "shooter_velocity_of",
        step = "projectile_flight_step",
        ray = "world_raycast",
        tree_valid = "speedtree_valid",
        tree_type = "speedtree_type",
        shield = "shield_blocks",
        entity_of = "entity_of_unit",
        hostile = "hostile_of",
        dead = "dead_of",
    }) do
        calls[role] = assert(judge:routine(name))
    end
    local constants = {}
    for role, name in pairs({
        one = "fire_speed_unit",
        caliber_scale = "projectile_caliber_scale",
        drag_area = "projectile_drag_area",
        drag_air = "projectile_drag_air",
        mass_scale = "projectile_mass_scale",
        limit = "projectile_distance_limit",
        floor = "projectile_speed_floor",
        lift = "impact_lift_at",
    }) do
        constants[role] = read:value(weapon.game + n[name], "f32")
    end
    constants.no_entity = read:value(weapon.game + n.entity_none_at, "u32")
    local numbers = {
        inherit_mask = n.projectile_inherit_mask,
        motion_stride = n.physics_motion_stride,
        motion_gravity = n.physics_motion_gravity,
        motion_speed = n.physics_motion_speed,
        motion_damping = n.physics_motion_damping,
        path_bit = n.projectile_path_filter_bit,
        filter_default = n.projectile_filter_default,
        filter_base = n.projectile_filter_base,
        velocity = n.projectile_record_velocity,
        hits = n.projectile_path_hits,
        hit_stride = n.raycast_hit_stride,
        record_at = n.hit_record_at,
        flags_at = n.hit_record_flags_at,
        unit_at = n.hit_record_unit_at,
        normal_at = n.hit_record_normal_at,
        material_at = n.hit_record_material_at,
        tree_flag = n.speedtree_hit_flag,
        near_miss = n.near_miss_material,
        skip_material = n.skip_hit_material,
        shield = n.shield_material,
        tree_stride = n.speedtree_pass_stride,
        tree_count = n.speedtree_pass_count,
        tree_value = n.speedtree_pass_value,
        tree_keep = n.speedtree_pass_keep,
        tree_low = n.speedtree_pass_low,
        tree_high = n.speedtree_pass_high,
        release_delay = n.throw_release_delay_bits,
        water = n.water_material,
    }
    return setmetatable({
        weapon = weapon,
        equipment = equipment,
        panel = panel,
        read = read,
        judge = judge,
        n = n,
        projectile = Projectile.new(weapon),
        launch = Launch.new(weapon),
        calls = calls,
        constants = constants,
        numbers = numbers,
        state = {},
        request = {},
        modifier = assert(judge:routine("explosion_modifier_of")),
        blast_numbers = {
            kind_count = n.explosion_kind_count,
            explosion_stride = n.explosion_info_stride,
            radius_inner = n.explosion_radius_inner,
            radius_outer = n.explosion_radius_outer,
        },
    }, Feature)
end
function Feature:draws(values)
    return values["hud.trajectory"] ~= 0 or values["hud.impact_marker"] ~= 0
end
function Feature:wanted(values)
    return self:draws(values) or values["hud.throw_distance"] == 1
end
function Feature:awake(inputs)
    return inputs.aiming == true or inputs.holding == true
end
function Feature:predict(inputs, fuse, mode, mark)
    local weapon, read, judge, n, equipment = self.weapon, self.read, self.judge, self.n, self.equipment
    local projectile, launch = self.projectile, self.launch
    if inputs.switching == true then
        projectile:clear()
        launch:clear()
        return
    end
    projectile:observe(inputs.aiming, equipment.fire, equipment.fire_record, equipment.charge)
    local c4 = inputs.aiming == true and projectile.blob == nil and launch:c4(equipment.options)
    local shooter_record = weapon:record(inputs.avatar)
    local shooter
    if shooter_record ~= nil then
        shooter = read:value(shooter_record + n.record_engine_unit, "u32")
    end
    local v = launch:observe(inputs, equipment.cell, projectile, c4, shooter, fuse)
    if projectile.flies then
        v = v or {}
        local info = projectile:details()
        v.mass, v.drag, v.gravity, v.substeps, v.life = info.mass, info.drag, info.gravity, info.substeps, info.life
        v.caliber, v.arming, v.flags, v.filter = info.caliber, info.arming, info.flags, info.filter
        v.explode_angle, v.ricochets, v.ricochet_angle, v.ricochet_speed =
            info.explode_angle, info.ricochets, info.ricochet_angle, info.ricochet_speed
        v.entity, v.unit = projectile.id, read:value(projectile.record + n.record_engine_unit, "u32")
        v.info, v.speed, v.scale, v.aim = projectile.info, projectile.speed, projectile.scale, projectile.aim
        v.impact = projectile.projectile.impact
    end
    if v == nil then
        return
    end
    self.from_hand = v.from_hand
    local system = weapon:manager(n.projectile_system)
    if system ~= nil then
        v.filters = read:ptr(system + n.projectile_filter_table)
    end
    v.world, v.eye, v.shooter, v.shooter_id = self.world, inputs.eye, shooter, inputs.avatar
    v.dt, v.trees, v.mark = self.panel.dt, weapon.game + n.speedtree_pass_table, mark
    if mark then
        v.factions, v.health = weapon:manager(n.faction_manager), weapon:manager(n.health_manager)
        if v.factions ~= nil then
            v.faction = weapon:find(v.factions + n.faction_map, inputs.avatar, weapon.invalid_player)
        end
    end
    local k = self.constants
    v.one, v.caliber_scale, v.drag_area, v.drag_air = k.one, k.caliber_scale, k.drag_area, k.drag_air
    v.mass_scale, v.limit, v.floor, v.lift, v.no_entity = k.mass_scale, k.limit, k.floor, k.lift, k.no_entity
    if
        v.entity == nil
        or v.unit == nil
        or v.shooter == nil
        or v.dt == nil
        or v.filters == nil
        or v.world == nil
        or (mark and (v.factions == nil or v.health == nil))
        or k.one == nil
        or k.caliber_scale == nil
        or k.drag_area == nil
        or k.drag_air == nil
        or k.mass_scale == nil
        or k.limit == nil
        or k.floor == nil
        or k.no_entity == nil
    then
        return
    end
    local path
    if mode == 1 or mode == 2 then
        path = self.state.path or {}
        self.state.path = path
    end
    local flight = Flight.predict(read, judge, self.calls, self.state, v, self.numbers, path)
    if flight == nil or flight.finish == nil then
        return flight
    end
    local blast
    if mode == 1 or mode == 3 then
        local book = weapon:manager(n.explosion_modifier_table)
        local cause = v.entity
        if c4 then
            cause = weapon.invalid_entity
        end
        if book ~= nil then
            local outer = judge:call(self.modifier, book, cause, n.explosion_scale_key)
            local inner = judge:call(self.modifier, book, cause, n.explosion_inner_scale_key)
            local impact, expire = launch.kind, launch.kind
            if projectile.flies then
                impact, expire = projectile.projectile.impact, projectile.projectile.expire
            end
            if outer ~= nil and inner ~= nil then
                blast = Flight.blast(read, {
                    at = flight,
                    explosions = weapon.game + n.explosion_info_table,
                    impact = impact,
                    expire = expire,
                    scale_outer = outer,
                    scale_inner = inner,
                }, self.blast_numbers)
            end
        end
    end
    return flight, blast, shooter
end
function Feature:locate(inputs)
    if self.observer ~= nil then
        return
    end
    local shooter = self.shooter
    if shooter == nil then
        local record = self.weapon:record(inputs.avatar)
        if record ~= nil then
            shooter = self.read:value(record + self.n.record_engine_unit, "u32")
        end
    end
    if shooter ~= nil and shooter > 0 then
        local at = self.judge:call(self.calls.position, shooter, 0)
        if at ~= nil and at ~= 0 then
            self.observer = self.read:vector(at, 3)
        end
    end
end
function Feature:step(values, inputs, fuse, guide, clock)
    local mode, marker = values["hud.trajectory"], values["hud.impact_marker"]
    self.from_hand, self.observer, self.shooter = nil, nil, nil
    if (not self:wanted(values) and not guide) or not self.panel.ready then
        self:close()
        return
    end
    local world = inputs.world
    if self.world ~= world then
        self.state, self.bounced = {}, nil
        self.projectile:clear()
        self.launch:clear()
    end
    self.world = world
    local flight, blast, shooter
    if world ~= nil and self:awake(inputs) then
        flight, blast, shooter = self:predict(inputs, fuse, mode, marker ~= 0)
    else
        self.projectile:clear()
        self.launch:clear()
        self.state = {}
    end
    self.flight = flight
    self.shooter = shooter
    if shooter ~= nil and (mode == 1 or mode == 3) then
        self:locate(inputs)
    end
    self.row, self.shot = nil, nil
    if not self:draws(values) then
        self.bounced = nil
        return
    end
    if flight == nil or flight.finish == nil then
        return
    end
    local now = flight.bounce == true
    if
        self.bounced == nil
        or now == self.bounced
        or (clock ~= nil and self.agreed ~= nil and clock - self.agreed >= HOLD)
    then
        self.bounced, self.agreed = now, clock
    end
    if mode == 1 or mode == 3 then
        local row = not self.bounced and blast or {}
        row.key, row.at = "shot", flight.finish
        self.row = row
    end
    local shot, alpha = self.request, math.floor(values["hud.trajectory.line_alpha"]) * 16777216
    shot.at, shot.normal, shot.style = flight.finish, flight.normal, marker - 1
    shot.colour, shot.edge = alpha + WHITE, alpha + BLACK
    shot.path = flight.path
    shot.mark = marker ~= 0
            and flight.seen == true
            and alpha + (self.bounced and YELLOW or flight.foe == true and FOE or WHITE)
        or nil
    self.shot = shot
end
function Feature:close()
    self.projectile:clear()
    self.launch:clear()
    self.world, self.flight, self.from_hand, self.observer, self.row, self.shot, self.state =
        nil, nil, nil, nil, nil, nil, {}
    self.shooter, self.bounced, self.agreed = nil, nil, nil
end
return Feature
end
modules["features.weapon_3d"] = function(require)
local Display = require("game.weapon_panel")
local Wake = require("game.wake")
local Reload = require("game.reload")
local Cycle = require("game.weapon_cycle")
local Feature = {}
Feature.__index = Feature
local NONE = { 0, 0 }
function Feature.new(ui, panel, weapon, equipment, pack)
    return setmetatable({
        ui = ui,
        panel = panel,
        weapon = weapon,
        equipment = equipment,
        pack = pack,
        display = Display.new(ui),
        wake = Wake.new(11),
        reload = Reload.new(weapon),
        cycle = Cycle.new(weapon),
        events = {},
        sample = { slots = { {}, {}, {} } },
    }, Feature)
end
local function shown_reserve(ammo, pack)
    if ammo.throwing then
        return nil
    end
    if ammo.reserve ~= nil then
        return ammo.reserve
    end
    return pack.remaining
end
function Feature:wanted(values)
    return values["hud.weapon3d.ammo"] == 1
        or values["hud.weapon3d.reserve"] == 1
        or values["hud.weapon3d.throwables"] == 1
        or values["hud.weapon3d.stims"] == 1
        or values["hud.weapon3d.functions"] == 1
        or values["hud.weapon3d.fire_mode"] == 1
        or values["hud.weapon3d.zeroing"] == 1
        or values["hud.weapon3d.arc"] == 1
end
function Feature:observe(values, ready, clock, inputs, sample, slots, reloading, map)
    self.enabled, self.ammo, self.awake = self:wanted(values), nil, nil
    if not self.enabled or not ready then
        self.wake:clear()
        self.reload:clear()
        if not self.enabled then
            self.display:close()
        end
        return
    end
    local panel, read, n = self.panel, self.weapon.read, self.weapon.n
    local equipment = self.equipment
    local ammo = sample.ammo
    self.ammo = ammo
    local count_on, reserve_on, arc_on =
        values["hud.weapon3d.ammo"] == 1, values["hud.weapon3d.reserve"] == 1, values["hud.weapon3d.arc"] == 1
    local throwables_on, stims_on, functions_on =
        values["hud.weapon3d.throwables"] == 1, values["hud.weapon3d.stims"] == 1, values["hud.weapon3d.functions"] == 1
    local mode_on, zero_on = values["hud.weapon3d.fire_mode"] == 1, values["hud.weapon3d.zeroing"] == 1
    local v = self.events
    for index = 1, 11 do
        v[index] = nil
    end
    if count_on or reserve_on or arc_on then
        v[1] = read:value(panel.base + n.self_panel_weapon_picture, "hex64")
    end
    if reserve_on then
        v[2] = shown_reserve(ammo, self.pack)
    end
    if count_on then
        v[3] = ammo.text
    end
    if functions_on then
        v[4], v[9] = slots[1][2], equipment.throwable.fuse_choice
    end
    if mode_on then
        v[5] = slots[2][2]
    end
    if zero_on then
        v[6] = slots[3][2]
    end
    if count_on or reserve_on or arc_on or throwables_on or functions_on or mode_on or zero_on then
        v[7] = equipment.wield
    end
    if stims_on then
        v[8] = ammo.stims
    end
    if arc_on then
        v[10] = ammo.drawn
    end
    if throwables_on then
        v[11] = ammo.throwables_unheld
    end
    local held = inputs.engaged == true
        or equipment.charge.charging == true
        or reloading == true
        or map == true
        or (ammo.magazine_low == true and (count_on or arc_on))
        or (ammo.reserve_low == true and reserve_on)
    self.awake = self.wake:step(clock, v, held, values["hud.world3d.fire_time"])
end
function Feature:prepare(parent, frame, values)
    if not self.enabled then
        return false
    end
    local display = self.display
    local alive = self.ui:alive(display.gauge.root)
    if alive == nil then
        return nil
    end
    if not alive or display.parent ~= parent or display.values ~= values then
        display:close()
        display:create(parent, frame, values)
    end
    return self.awake == true or not display.filled
end
function Feature:content(values, inputs, picked, record, ammo, slots, fuse, reloading)
    local sample, panel, weapon = self.sample, self.panel, self.weapon
    local equipment = self.equipment
    local charge, throwable = equipment.charge, equipment.throwable
    sample.ammo, sample.reserve = ammo.text, shown_reserve(ammo, self.pack)
    sample.throwables, sample.stims = ammo.throwables_unheld, ammo.stims
    sample.wielded = equipment.wield ~= nil and equipment.wield == picked
    for index = 1, 3 do
        sample.slots[index][1], sample.slots[index][2], sample.slots[index][3] = unpack(slots[index], 1, 3)
    end
    sample.fuse = throwable
    sample.style = nil
    if
        values["hud.weapon3d.ammo"] == 1
        or values["hud.weapon3d.arc"] == 1
        or values["hud.weapon3d.reserve"] == 1
        or values["hud.weapon3d.throwables"] == 1
        or values["hud.weapon3d.stims"] == 1
    then
        sample.style = panel:style(ammo.throwing, ammo.reserve ~= nil)
    end
    sample.outline, sample.fill, sample.magazine_size = nil, nil, nil
    if values["hud.weapon3d.reserve"] == 1 and sample.reserve ~= nil then
        sample.outline, sample.fill = weapon:ammo_icons(record)
        sample.magazine_size = panel:magazine_size()
    end
    sample.throwable_icon, sample.throwable_size = nil, nil
    if values["hud.weapon3d.throwables"] == 1 and sample.throwables ~= nil then
        sample.throwable_icon, sample.throwable_size = panel:throwable_icon()
    end
    if values["hud.weapon3d.functions"] == 1 then
        throwable:wheel(equipment.wield)
    end
    sample.empty, sample.progress, sample.cycle, sample.charge, sample.ready = nil, nil, nil, nil, nil
    if values["hud.weapon3d.arc"] == 1 then
        self.reload:observe(inputs.avatar, equipment.fire, equipment.fire_record, self.pack.remaining, reloading)
        self.cycle:shot(equipment.fire, ammo.hidden, equipment.fire_count, charge.index)
        sample.progress = self.reload.share
        if sample.progress == nil then
            throwable:progress(inputs.avatar, equipment.cell, equipment.inventory, ammo.throwing, ammo.throwables, fuse)
            sample.progress = throwable.share
        end
        if sample.progress == nil then
            self.cycle:melee(inputs.avatar, equipment.avatar_row, inputs.melee, ammo.hidden, equipment.fire_count)
            sample.progress = self.cycle.progress
        end
        sample.cycle, sample.charge, sample.ready = self.cycle.left, charge.share, charge.ready_share
        if
            self.reload.share == nil
            and charge.share == nil
            and charge.charging ~= true
            and not ammo.throwing
            and picked ~= nil
        then
            sample.empty = ammo.empty
        end
    else
        self.reload:clear()
    end
end
function Feature:put(frame, values, fixed, spot, keep, pixel, changed)
    if not self.enabled or self.display.parent == nil then
        return false, NONE
    end
    local display = self.display
    if changed then
        display:put(frame, self.sample)
    else
        display:update(frame)
    end
    display.gauge:place(fixed, spot, display.size, values["hud.weapon3d.gauge_gap"], keep, pixel)
    return display.gauge:display(
        self.awake,
        values["hud.world3d.idle"],
        values["hud.weapon3d.opacity"],
        self.ui.n.widget_fade_seconds[1]
    ),
        display.size
end
function Feature:hide()
    self.display:hide()
end
function Feature:close()
    self.display:close()
    self.wake:clear()
    self.reload:clear()
end
return Feature
end
modules["features.weapon_hud"] = function(require)
local Hud = {}
Hud.__index = Hud
function Hud.new(panel, line)
    return setmetatable({ panel = panel, line = line, clock = 0, frame = 0, values = { {}, {}, {} } }, Hud)
end
function Hud:restore()
    if self.width_state == nil then
        return
    end
    local panel = self.panel.editable and self.panel.base or nil
    local state = self.line:reset(panel, self.width_state == "requested")
    if state == "cleared" then
        self.width_state = nil
    elseif state ~= nil then
        self.width_state = state
    end
end
function Hud:prepare(ammo, functions, fire_mode, zeroing)
    local panel, line = self.panel, self.line
    self.visible = false
    self.frame = self.frame + 1
    local dt = panel.dt
    self.clock = self.clock + (dt or 0)
    local parent, row, awake
    if ammo or functions or fire_mode or zeroing then
        parent, row, awake = panel:weapon_mount()
    end
    if parent == nil then
        if line.parent ~= nil then
            line:close()
        end
        self.next_content = nil
        self:restore()
        return
    end
    local alive = line:alive()
    if alive == nil then
        return
    end
    local fresh = line.parent ~= parent
        or line.row ~= row
        or alive == false
        or self.ammo ~= ammo
        or self.functions ~= functions
        or self.fire_mode ~= fire_mode
        or self.zeroing ~= zeroing
    if fresh then
        if line.parent ~= nil then
            line:close()
        end
        line:create(parent, row, self.frame, ammo, functions, fire_mode, zeroing)
        self.ammo, self.functions, self.fire_mode, self.zeroing = ammo, functions, fire_mode, zeroing
        self.next_content = nil
    end
    if not awake then
        line:show(false)
        self.next_content = nil
        self:restore()
        return
    end
    line:show(true)
    self.visible = true
    return dt == nil or self.next_content == nil or self.clock >= self.next_content
end
function Hud:put(count, slots)
    if self.ammo then
        self.line:put(count)
    end
    local values = self.values
    if self.functions then
        values[1][1], values[1][2], values[1][3] = unpack(slots[1], 1, 3)
    end
    if self.fire_mode then
        values[2][1], values[2][2], values[2][3] = unpack(slots[2], 1, 3)
    end
    if self.zeroing then
        values[3][1], values[3][2], values[3][3] = unpack(slots[3], 1, 3)
    end
    self.next_content = self.clock + 1 / 30
end
function Hud:finish()
    if not self.visible then
        return
    end
    local line = self.line
    line:update(self.frame, self.values)
    if line:extend(line.row, line.parent) then
        self.width_state = "applied"
    else
        self:restore()
    end
end
function Hud:close()
    self.line:close()
    self:restore()
end
return Hud
end
modules["features.world_hud"] = function(require)
local Stage = require("game.world_stage")
local Body = require("features.body")
local Stratagem = require("features.stratagem")
local Pack = require("features.pack")
local Weapon3d = require("features.weapon_3d")
local Cooldown = require("features.stratagem_cooldown")
local Pose = require("game.world_pose")
local Hud = {}
Hud.__index = Hud
local CENTRE = { 0, 0 }
local NONE = { 0, 0 }
function Hud.new(ui, port, panel, weapon, equipment, inputs, extension, pick)
    local stage = Stage.new(ui, port, { 140, 90 })
    local stratagem, pack = Stratagem.new(ui, panel, weapon, pick), Pack.new(ui, weapon)
    return setmetatable({
        stage = stage,
        panel = panel,
        weapon = weapon,
        inputs = inputs,
        body = Body.new(ui, panel),
        pack = pack,
        extension = extension,
        cooldown = Cooldown.new(ui, panel, stratagem.inputs),
        equipment = equipment,
        weapon_view = Weapon3d.new(ui, panel, weapon, equipment, pack.values),
        stratagem = stratagem,
        stratagem_rack = stage:rack({ 140, 90 }),
        sequence = 0,
        hand = stage:rack({ 140, 90 }),
        frame = {},
        placement = {},
        spread = {},
        stratagem_spread = {},
        listing = { offset = {} },
        icon = { offset = {} },
        aim = { offset = {} },
        aim_body = { offset = {} },
        rest = { offset = {} },
    }, Hud)
end
local function scene_config(scene, values, name)
    local prefix = "hud.world3d." .. name
    scene.offset[1], scene.offset[2] = values[prefix .. "_x"], values[prefix .. "_y"]
    scene.radius, scene.tau, scene.ceiling =
        values[prefix .. "_radius"], values[prefix .. "_tau"], values[prefix .. "_ceiling"]
end
function Hud:configure(values)
    if self.values == values then
        return
    end
    self.values = values
    self.panel:configure(values)
    scene_config(self.aim, values, "aim")
    scene_config(self.aim_body, values, "aim_body")
    scene_config(self.rest, values, "weapon")
    scene_config(self.listing, values, "stratagem")
    scene_config(self.icon, values, "stratagem_icon")
    self.spread[1], self.spread[2] = values["hud.world3d.screen_x"], values["hud.world3d.screen_y"]
    self.stratagem_spread[1], self.stratagem_spread[2] =
        values["hud.world3d.stratagem_screen_x"], values["hud.world3d.stratagem_screen_y"]
    self.frame.share = 0.14 * values["hud.world3d.size"]
    self.frame.mix, self.frame.cap = values["hud.world3d.tilt_mix"], values["hud.world3d.tilt_cap"]
end
function Hud:wanted(values)
    return values["hud.weapon3d.health"] == 1
        or values["hud.weapon3d.stamina"] == 1
        or values["hud.weapon3d.pack"] == 1
        or values["hud.weapon3d.cooldown"] == 1
        or self.weapon_view:wanted(values)
        or values["hud.stratagem3d"] == 1
        or self.extension.wanted
end
function Hud:hide_hand()
    self.body:hide()
    self.pack:hide()
    self.weapon_view:hide()
    self.cooldown:hide()
end
function Hud:hide()
    self:hide_hand()
    self.stratagem:hide()
    self.extension.hide()
end
function Hud:begin(values)
    self.sequence = self.sequence + 1
    self:configure(values)
    self.ready, self.clock, self.hand_ready, self.content_due = nil, nil, false, false
    if self:wanted(values) then
        self.ready = self.inputs.ready
    end
    if self.ready then
        self.clock = self.panel:clock()
    end
    self.ball_needed = self.stratagem:prepare(
        values["hud.stratagem3d"] == 1,
        self.inputs,
        self.extension.wanted,
        values["hud.weapon3d.cooldown"] == 1
    )
    local weapon = self.ready and self.weapon_view:wanted(values)
    local centre = self.ready
        and values["hud.world3d.lock"] == 1
        and (
            values["hud.weapon3d.health"] == 1
            or values["hud.weapon3d.stamina"] == 1
            or values["hud.weapon3d.pack"] == 1
        )
    return weapon, weapon or centre
end
function Hud:prepare(values, avatar, seated, seat_row, wield, player, players, reloading, slots, sample)
    local stage, inputs, body, panel = self.stage, self.inputs, self.body, self.panel
    if not panel.editable then
        self:close()
        return
    end
    local alive = stage.ui:alive(stage.root)
    if alive == nil then
        return
    end
    if not alive then
        self:close()
    end
    local ready, clock = self.ready, self.clock
    local pack_on = values["hud.weapon3d.pack"] == 1
    local weapon_on = self.weapon_view:wanted(values)
    local worn, drawn, spare, wield_record, key
    local pack_needed = pack_on or (weapon_on and values["hud.weapon3d.reserve"] == 1)
    local health_on = values["hud.weapon3d.health"] == 1
    local map
    if ready and (health_on or weapon_on or pack_on) then
        map = self.weapon:map_open(panel.mission - panel.n.hud_widgets_mission_hud)
    end
    local body_on = body:observe(values, ready, clock, sample, map)
    if ready and pack_needed then
        worn, drawn, spare = sample.worn, sample.gauge, sample.spare
    end
    if ready and (weapon_on or inputs.aiming == true or (pack_needed and not spare)) then
        wield_record = self.equipment.record
        if wield_record == nil and not weapon_on then
            wield_record = self.weapon:record(wield)
        end
    end
    if pack_needed and not spare then
        key = self.weapon:key(wield_record)
    end
    local ammo_shown = values["hud.weapon3d.ammo"] == 1 or values["hud.weapon3d.arc"] == 1
    if ready and pack_needed then
        self.pack.values:observe(avatar, key, spare, worn, drawn, values["hud.weapon3d.reserve"] == 1)
    end
    self.pack:observe(
        pack_on,
        clock,
        worn,
        drawn,
        values["hud.world3d.fire_time"],
        map == true or (sample ~= nil and sample.pack_low == true),
        ammo_shown and wield or nil
    )
    self.weapon_view:observe(values, ready, clock, inputs, sample, slots, reloading, map)
    local showing = self.stratagem:observe(
        values["hud.stratagem3d"] == 1,
        inputs,
        player,
        players,
        self.extension.wanted,
        self.equipment.cell
    )
    if not showing or not self.extension.wanted or self.stratagem.inputs.listing then
        self.extension.close()
    end
    local cooldown_on =
        self.cooldown:observe(values, ready, clock, avatar, players, self.stratagem.inputs.listing == true)
    if not body_on and not pack_on and not weapon_on and not cooldown_on and not showing then
        if stage.root ~= nil then
            stage:close()
        end
        return
    end
    inputs:place(panel, seated, seat_row, wield, wield_record, reloading)
    if not stage:prepare(panel) then
        self:hide()
        return
    end
    if not ready or inputs.clear ~= true then
        self:hide()
        stage:hide()
        stage:submit(panel.dt)
        return
    end
    local lock = values["hud.world3d.lock"]
    local fixed = lock ~= 0 or inputs.pinned == true
    self.frame.fixed = fixed
    if not stage:place(self.frame, inputs.body, true) then
        self:hide()
        stage:submit(panel.dt)
        return
    end
    if showing then
        local scene = self.stratagem.inputs.listing and self.listing or self.icon
        local placement = self.placement
        placement.fixed, placement.offset, placement.scene, placement.dt =
            fixed, fixed and self.stratagem_spread or scene.offset, scene, panel.dt
        if stage:place_rack(self.stratagem_rack, placement, inputs.anchor, inputs.anchor_node) then
            if values["hud.stratagem3d"] == 1 then
                self.stratagem:put(self.stratagem_rack.node.at, self.sequence, values)
            end
            if self.extension.wanted and not self.stratagem.inputs.listing then
                self.extension.put(self.stratagem_rack.node.at, self.sequence)
            end
        else
            self.stratagem:hide()
            self.extension.hide()
        end
    else
        stage:hide_rack(self.stratagem_rack)
    end
    if showing and values["hud.stratagem3d"] == 1 then
        self:hide_hand()
        stage:hide_rack(self.hand)
        stage:submit(panel.dt)
        return
    end
    local scene = self.rest
    if inputs.fire_found == true then
        scene = self.aim
    elseif inputs.aiming == true then
        scene = self.aim_body
    end
    local spot = scene.offset
    if fixed then
        spot = CENTRE
        if inputs.pinned == true or lock == 2 or inputs.engaged == true then
            spot = self.spread
        end
    end
    local placement = self.placement
    placement.fixed, placement.offset, placement.scene, placement.dt = fixed, spot, scene, panel.dt
    if stage:place_rack(self.hand, placement, inputs.anchor, inputs.anchor_node) then
        self.hand_ready = true
        self.content_due = self.weapon_view:prepare(self.hand.node.at, self.sequence, values)
        return self.content_due
    else
        self:hide_hand()
    end
    stage:submit(panel.dt)
end
function Hud:finish(values)
    if not self.hand_ready then
        return
    end
    local placement, stage, hand = self.placement, self.stage, self.hand.node.at
    local fixed, spot = placement.fixed, placement.offset
    local keep, pixel = Pose.keep(placement.scene.tau, self.panel.dt), stage.pose:pixel()
    local weapon_lit, size = false, NONE
    if self.content_due ~= nil then
        weapon_lit, size = self.weapon_view:put(self.sequence, values, fixed, spot, keep, pixel, self.content_due)
    end
    local body_lit = self.body:put(hand, values, fixed, spot, size, keep, pixel)
    local pack_lit = self.pack:put(hand, values, fixed, spot, size, keep, pixel)
    local cooldown_lit = self.cooldown:put(hand, self.sequence, values, fixed, spot, size, keep, pixel)
    if not weapon_lit and not body_lit and not pack_lit and not cooldown_lit then
        stage:hide_rack(self.hand)
    end
    stage:submit(self.panel.dt)
end
function Hud:close()
    self.extension.close()
    self.stratagem:close()
    self.weapon_view:close()
    self.body:close()
    self.pack:close()
    self.cooldown:close()
    self.stage:close()
end
return Hud
end
modules["game.ability_script"] = function(require)
local Bytes = require("native.bytes")
local X64 = require("game.x64")
local M = {}
local floor = math.floor
local NO_EVENT = 2 ^ 30
local EDX = 2
local BRANCH = {
    je = function(a, b)
        return a == b
    end,
    jne = function(a, b)
        return a ~= b
    end,
    ja = function(a, b)
        return a > b
    end,
    jae = function(a, b)
        return a >= b
    end,
    jb = function(a, b)
        return a < b
    end,
    jbe = function(a, b)
        return a <= b
    end,
    jg = function(a, b)
        return a > b
    end,
    jge = function(a, b)
        return a >= b
    end,
    jl = function(a, b)
        return a < b
    end,
    jle = function(a, b)
        return a <= b
    end,
}
local function is_reg32(o)
    return o ~= nil and o.kind == "reg" and o.w == 32
end
local function is_imm(o)
    return o ~= nil and o.kind == "imm"
end
local function is_al(o)
    return o ~= nil and o.kind == "reg" and o.w == 8 and o.n == 0 and not o.hi
end
local function has(set, n)
    return floor(set / 2 ^ n) % 2 == 1
end
local function with_reg(set, n)
    if has(set, n) then
        return set
    end
    return set + 2 ^ n
end
local function without_reg(set, n)
    if has(set, n) then
