                        work[#work + 1] = {
                            i = dest,
                            alias = alias,
                            test = test,
                            asked = asked,
                            r8 = r8,
                            via = v,
                            last = last,
                            state = state,
                            dx = dx,
                            r9 = r9,
                            eax = eax,
                            versus = versus,
                            answered = answered,
