            span.arc, span.base = index, rerun and played or 0
        end
    end
    return span,
        { step = step_of(span.path, frame, span.bolt), elapsed = played - span.base, length = total - span.base },
        events
end
local ROUNDS_KEYS = {
    "r0",
    "r1",
    "sel",
    "cap0",
    "cap1",
    "thr0",
    "thr1",
    "kind0",
    "kind1",
    "chambered",
    "reserve",
    "amount",
    "from_pack",
    "stage",
    "pack",
    "need",
    "worn",
}
local ROUNDS_REQUIRED = 14
function M.rounds_state(v)
    local state = {}
    for index = 1, ROUNDS_REQUIRED do
        local key = ROUNDS_KEYS[index]
        if type(v[key]) ~= "number" then
            return nil
        end
        state[key] = v[key]
    end
    if type(v.chamber) ~= "number" then
        return nil
    end
    state.chamber = v.chamber ~= 0 and 1 or 0
    state.same = state.kind0 == state.kind1 and 1 or 0
    state.kind0, state.kind1 = nil, nil
    if state.chambered ~= 0 then
        state.chambered = 1
    end
    if state.from_pack ~= 0 then
        if v.pack == nil then
            return nil
        end
        state.from_pack = 1
        state.pack = v.pack
    end
    state.need = v.need
    if state.need ~= nil then
        state.worn = v.worn
    end
    return state
end
local CODE_CHUNK = 4096
local function code_reader(read, game)
    local chunks = {}
    return function(rva, count)
        local base = rva - rva % CODE_CHUNK
        if rva + count <= base + CODE_CHUNK then
            local text = chunks[base]
            if text == nil then
                text = read:text(game + base, CODE_CHUNK) or false
                chunks[base] = text
            end
            if text then
                return string.sub(text, rva - base + 1, rva - base + count)
            end
        end
        return read:text(game + rva, count)
    end
end
local lengths = nil
local function lengths_of(span, n, bytes)
    if lengths == nil then
        lengths = M.length_reader(span, n.length, bytes) or false
    end
    return lengths
end
function M.calling_frame_in(read, n, id, targets)
    local game = read:module("game")
    if game == nil then
        return nil
    end
    local span = code_reader(read, game)
    local cap = lengths_of(span, n, read.bytes)
    if not cap then
        return false
    end
    return M.calling_frame(span, n, id, cap, targets, read.bytes) or false
end
local walked = {}
function M.timeline(read, state, v, n, state_of)
    if type(v.ability) ~= "number" or type(v.frame) ~= "number" or v.entity == nil then
        state.span = nil
        return nil
    end
    local facts = walked[v.ability]
    if facts == nil then
        local game = read:module("game")
        if game == nil then
            return nil
        end
        local span = code_reader(read, game)
        local cap = lengths_of(span, n, read.bytes)
        facts = cap and M.ability(span, n, v.ability, cap, read.bytes) or false
        walked[v.ability] = facts
    end
    if facts == false then
        return nil
    end
    local result
    state.span, result = M.advance(n, facts, state.span, v.entity, v.ability, v.frame, v.chamber, state_of)
    return result
end
return M
end
modules["game.attackers"] = function(require)
local Attackers = {}
Attackers.__index = Attackers
function Attackers.new(weapon)
    return setmetatable({
        weapon = weapon,
        lob = {},
        lob_cache = {},
        keys = {},
        faction = assert(weapon.judge:routine("faction_includes")),
    }, Attackers)
end
local function records(read, manager, used, capacity, array)
    if manager == nil then
        return nil
    end
    local limit = read:value(manager + capacity, "u32")
    local base = read:ptr(manager + array)
    if used == nil or limit == nil or used > limit or base == nil then
        return nil
    end
    local out = {}
    for index = 0, used - 1 do
        local at = read:ptr(base + index * 8)
        if at == nil then
            return nil
        end
        out[#out + 1] = at
    end
    return out
end
function Attackers:observe(eagles)
    local weapon = self.weapon
    local read, judge, n = weapon.read, weapon.judge, weapon.n
    local keys = {}
    for id in pairs(eagles) do
        keys[id] = { id = id, aircraft = id }
    end
    local bomb_manager = weapon:manager(n.bombardment_manager)
    local count
    if bomb_manager ~= nil then
        count = read:value(bomb_manager + n.bombardment_count, "u32")
    end
    local bombs = records(read, bomb_manager, count, n.bombardment_capacity, n.bombardment_records)
    for _, at in ipairs(bombs or {}) do
        local id = read:value(at + n.bombardment_entity_id, "u32")
        if id ~= nil and keys[id] == nil then
            keys[id] = { id = id }
        end
    end
    local manager = weapon:manager(n.turret_manager)
    local used
    if manager ~= nil then
        used = read:value(manager + n.turret_used, "u32")
    end
    if manager ~= self.manager or used ~= self.used then
        local lob, cache = {}, {}
        local previous = self.lob_cache
        if manager ~= self.manager then
            previous = {}
        end
        local rows = records(read, manager, used, n.turret_capacity, n.turret_rows)
        local targeting = weapon:manager(n.targeting_manager)
        if targeting ~= nil then
            for _, at in ipairs(rows or {}) do
                local id = read:value(at + n.turret_entity_id, "u32")
                if id ~= nil then
                    local ours = previous[id]
                    if ours == nil then
                        local index = weapon:find(targeting + n.targeting_map, id, weapon.invalid_player)
                        local cells
                        if index ~= nil then
                            cells = read:ptr(targeting + n.targeting_rows)
                        end
                        ours = cells ~= nil
                            and read:value(cells + index * n.targeting_row_stride + n.targeting_arc_aim, "bool") == true
                            and judge:call(self.faction, 0, n.owner_faction_mask, id) == true
                    end
                    cache[id] = ours
                    if ours then
                        lob[id] = self.lob[id] or { id = id }
                    end
                end
            end
        end
        self.manager, self.used, self.lob, self.lob_cache = manager, used, lob, cache
    end
    for id, item in pairs(self.lob) do
        if keys[id] == nil then
            keys[id] = item
        end
    end
    self.keys = keys
end
function Attackers:clear()
    self.manager, self.used, self.lob, self.lob_cache, self.keys = nil, nil, {}, {}, {}
end
return Attackers
end
modules["game.charge"] = function(require)
local ratio = require("game.ratio")
local Charge = {}
