function Charge.new(weapon)
    return setmetatable({
        weapon = weapon,
        read = weapon.read,
        judge = weapon.judge,
        n = weapon.n,
        charge_open = assert(weapon.judge:routine("charge_open")),
        heat_open = assert(weapon.judge:routine("heat_open")),
