Core.predict = fly
function Core.heading(read, settings, n)
    return read:value(settings + n.block + n.read - n.copy, "f32")
end
function Core.blast(read, v, n)
    local at = v.at
    local finish, why, origin = at, nil, nil
    if at.why ~= nil or at.finish ~= nil then
        finish, why, origin = at.finish, at.why, at.origin
    end
    if finish == nil then
        return nil
    end
    local out = {}
    if v.eagle == nil and v.bombardment == nil then
        local got = blast(read, v, n, why == "hit" and v.impact ~= nil and v.impact ~= 0 and v.impact or v.expire, out)
        if got ~= nil and n.children ~= nil and got[3] ~= 0 then
            out.inner, out.outer = nil, nil
        end
        return out
    end
    local set = cells(read, n, v.bombardment ~= nil and "distribution" or "eagle", v.bombardment or v.eagle)
    if set == nil then
        return out
    end
    local got = blast(read, v, n, attack_kind(read, v, n, attack_projectile(read, v, n, set)), out)
    local children = got ~= nil and n.children ~= nil and got[3] ~= nil and got[3] ~= 0
    if v.bombardment ~= nil then
        distribution(n, set, finish, origin, out, children)
    elseif set[1] == n.pattern_mode then
        pattern(read, v, n, set, children, finish, origin, out)
    elseif set[1] == n.strafing_mode then
        strafe(v, n, set, finish, origin, out)
    else
        out.inner, out.outer = nil, nil
        local dx, dy, side = approach(v, n, finish, origin)
        if dx ~= nil then
            out.direction = { side * dx, side * dy }
        end
    end
    return out
end
function Core.scale(read, port, routines, state, v, n)
    local out = { outer = 1, inner = 1 }
    local entry = port:call(routines.tag_of, v.tags, v.kind)
    if type(entry) ~= "number" or entry == 0 then
        return out
    end
    local row = read:value(entry)
    if row == nil then
        return nil
    end
    local at = v.tags + row * n.tag_stride
    local count = read:value(at + n.tag_count)
    if count == nil then
        return nil
    end
    for index = 0, count - 1 do
        local hash = read:value(at + n.tag_hashes + index * 4)
        local part = hash == n.outer and "outer" or hash == n.inner and "inner" or nil
        if part ~= nil then
            local cell = buffer(port, state, "upgrade", "float", 1)
            if cell == nil then
                return nil
            end
            cell[0] = 1
            port:call(routines.upgrade, v.upgrades, cell, hash, 0)
            if not finite(cell[0]) then
                return nil
            end
            out[part] = cell[0]
        end
    end
    return out
end
return Core
end
modules["game.gauge"] = function(require)
local Resources = require("game.resources")
local Pose = require("game.world_pose")
local Gauge = {}
Gauge.__index = Gauge
local DIRECTIONS = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }
function Gauge.new(ui, inner, side)
    return setmetatable({ ui = ui, inner = inner, side = side, root_place = {}, arc_place = {} }, Gauge)
end
function Gauge:create(parent)
    local ui, n = self.ui, self.ui.n
    ui:context(parent, function()
        self.root = ui:frame(self.root)
        ui:size(self.root, 140, 90)
        ui:opacity(self.root, 0)
        self.arc = ui:frame(self.arc)
        ui:size(self.arc, 0, 0)
        ui:anchor(self.arc, 0.5, 0.5)
        ui:pivot(self.arc, 0.5, 0.5)
        ui:attach(self.root.at, self.arc)
        self.track = ui:image_node(self.track)
        self.fill = ui:image_node(self.fill)
        self.fill.gauge_value = nil
        local prefix = self.inner and "inner_" or "outer_"
        for _, node in ipairs({ self.track, self.fill }) do
            ui:size(node, 96, 96)
            ui:anchor(node, 0.5, 0.5)
            ui:pivot(node, 0.5, 0.5)
            ui:attach(self.arc.at, node)
        end
        ui:material(self.track, Resources[prefix .. "track"])
        ui:material(self.fill, Resources[prefix .. "fill"])
        ui:layer(self.track, n.crosshair_track_layer)
        ui:layer(self.fill, n.crosshair_fill_layer)
        ui:colour(self.track, 0, 0, 0)
        ui:colour(self.fill, 1, 1, 1)
        ui:opacity(self.track, self.inner and 0.4 or 0.5)
        ui:opacity(self.fill, self.inner and 0.8 or 1)
        ui:show(self.track, true)
        ui:attach(parent, self.root)
    end)
