        self.filled = true
    end
end
local function approach(ui, node, at, x, y, keep, pixel)
    local target_x, target_y = x, y
    if at[1] == nil then
        at[1], at[2] = x, y
    else
        x, y = x + (at[1] - x) * keep, y + (at[2] - y) * keep
        if Pose.near(x - target_x, y - target_y, pixel) then
            x, y = target_x, target_y
        end
    end
