end
Gauge.approach = approach
function Gauge.centre(side, toward, fixed, spot)
    if not fixed then
        return 0, 0
    end
    return (side * toward[1] * math.abs(spot[1]) - spot[1]) * 90, side * toward[2] * math.abs(spot[1]) * 90
