modules["game.pack"] = function(require)
local ratio = require("game.ratio")
local Pack = {}
Pack.__index = Pack
function Pack.new(weapon)
    local judge, n = weapon.judge, weapon.n
    local self = setmetatable(
        { weapon = weapon, read = weapon.read, judge = judge, n = n, out = assert(judge:buffer("uint32_t", 1)) },
        Pack
    )
    for _, name in ipairs({
        "worn_pack",
        "deposit_open",
        "drone_of_deposit",
        "minigame_settings",
        "shield_open",
        "entity_of_goid",
        "linked_ammo_target",
    }) do
        self[name] = assert(judge:routine(name))
    end
    self.one = self.read:value(weapon.game + n.fire_speed_unit, "f32")
    return self
end
function Pack:countdown(id)
    local weapon, read, judge, n = self.weapon, self.read, self.judge, self.n
    local manager = weapon:manager(n.minigame_manager)
    if manager == nil then
        return nil
    end
    local index = weapon:find(manager + n.minigame_map, id, weapon.invalid_player)
    if index == nil then
        return nil
    end
    local rows = read:ptr(manager + n.minigame_rows_at)
    local entities = read:ptr(manager + n.minigame_entities_at)
    if rows == nil or entities == nil then
        return self.one
    end
    local row = rows + index * n.minigame_rows_stride
    local entry = read:ptr(entities + index * n.minigame_entity_stride)
    local key
    if entry ~= nil then
        key = read:value(entry, "key64")
    end
    local book
    if key then
        book = judge:call(self.minigame_settings, judge:uint64_of(key))
    end
    local step = read:value(row + n.minigame_step, "u32")
    if book == nil or book == 0 or step == nil then
        return self.one
    end
    local authored = book + step * n.minigame_entry_stride
    if read:value(authored, "u32") ~= n.minigame_kind_countdown then
        return self.one
    end
    local left = read:value(row + n.minigame_countdown_left, "f32")
    if left == nil or left <= 0 then
        return self.one
    end
    local result = ratio(left, read:value(authored + n.minigame_countdown_info, "u32"))
    if result == nil then
        result = self.one
    end
    return result, true
end
function Pack:drone(id, deposits, index)
    local weapon, read, judge, n = self.weapon, self.read, self.judge, self.n
    if deposits == nil or index == nil then
        return nil
    end
    if judge:call(self.drone_of_deposit, deposits, self.out, id) == nil then
        return nil
    end
    local drone = tonumber(self.out[0])
    if drone == weapon.invalid_avatar then
        return nil
    end
    local gun = weapon:wield(drone)
    local manager = weapon:manager(n.arc_weapon_manager)
    if manager == nil then
        return nil
    end
    local found = weapon:find(manager + n.arc_weapon_map, gun, weapon.invalid_entity)
    if found == nil then
        return nil
    end
    local rows = read:ptr(manager + n.arc_weapon_rows_at)
    if rows == nil then
        return found
    end
    local row = rows + found * n.arc_weapon_rows_stride
    local wait = read:value(row + n.arc_weapon_wait, "f32")
    return found, ratio(wait, read:value(row + n.arc_weapon_interval, "f32")), wait ~= nil and wait > 0
end
function Pack:shield(id)
    local weapon, read, judge, n = self.weapon, self.read, self.judge, self.n
    local manager = weapon:manager(n.shield_manager)
    if manager == nil then
        return nil
    end
    local index = weapon:find(manager + n.shield_map, id, weapon.invalid_player)
    if index == nil then
        local links = weapon:manager(n.shield_link_manager)
        local link
        if links ~= nil then
            link = weapon:find(links + n.shield_link_map, id, weapon.invalid_entity)
        end
        local rows
        if link ~= nil then
            rows = read:ptr(links + n.shield_link_goids)
        end
        local goid
        if rows ~= nil then
            goid = read:value(rows + link * n.shield_link_goid_stride + n.shield_link_goid_at, "u32")
        end
        if goid ~= nil and judge:call(self.entity_of_goid, self.out, goid) ~= nil then
            index = weapon:find(manager + n.shield_map, tonumber(self.out[0]), weapon.invalid_player)
        end
    end
    if index == nil then
        return nil
    end
    local rows = read:ptr(manager + n.shield_rows_at)
    if rows == nil then
        return nil
    end
    local broken = read:value(rows + index * n.shield_rows_stride + n.shield_broken, "bool")
    if broken ~= true then
        return broken
    end
    local waits = read:ptr(manager + n.shield_waits_at)
    local wait
    if waits ~= nil then
        wait = read:value(waits + index * n.shield_wait_stride + n.shield_wait_left, "f32")
    end
    if wait == nil or wait <= 0 then
        return true
    end
    local records = read:ptr(manager + n.shield_records)
    local record
    if records ~= nil then
        record = read:ptr(records + index * n.shield_records_stride)
    end
    local book
    if record ~= nil then
        book = judge:call(self.shield_open, record)
    end
    local total
    if book ~= nil and book ~= 0 then
        total = read:value(book + n.shield_wait_total, "f32")
    end
    return true, ratio(wait, total), true
end
function Pack:observe(avatar, wield_key, spare_on, worn, gauge, reserve_shown)
    self.share, self.left, self.remaining, self.busy, self.covered, self.linked = nil, nil, nil, nil, nil, nil
    if worn then
        self.share = gauge
    end
    if not worn and spare_on then
        return
    end
    local weapon, read, judge, n = self.weapon, self.read, self.judge, self.n
    local inventory = weapon:manager(n.inventory_manager)
    if inventory == nil or avatar == nil then
        return
    end
    if judge:call(self.worn_pack, inventory, self.out, avatar) == nil then
        return
    end
    local id = tonumber(self.out[0])
    if id == weapon.invalid_entity then
        return
    end
    local record = weapon:record(id)
    local book
    if record ~= nil then
        book = judge:call(self.deposit_open, record)
    end
    if book == 0 then
        book = nil
    end
    local deposits, index
    if book ~= nil then
        deposits = weapon:manager(n.deposit_manager)
        if deposits ~= nil then
            index = weapon:find(deposits + n.deposit_map, id, weapon.invalid_entity)
        end
        if not spare_on and wield_key ~= nil then
            local feeds = read:value(book + n.deposit_instance_feeds_resource, "hex64")
            if feeds ~= nil and feeds == wield_key then
                local rows
                if index ~= nil then
                    rows = read:ptr(deposits + n.deposit_rows_at)
                end
                if rows ~= nil then
                    self.remaining = read:value(rows + index * n.deposit_rows_stride + n.deposit_remaining, "u32")
                end
                self.covered = reserve_shown == true and self.remaining ~= nil
            end
        end
        if worn and not spare_on and self.covered == nil then
            self.linked = id
        end
    end
    if not worn or self.covered then
        return
    end
    local arc, broken, alternate, busy
    if book ~= nil then
        if read:value(book + n.deposit_drone_path, "hex64") ~= nil then
            arc, self.left, busy = self:drone(id, deposits, index)
        else
            alternate, busy = self:countdown(id)
        end
    elseif gauge == nil or gauge <= 0 then
        broken, self.left, busy = self:shield(id)
    end
    if arc == nil and broken ~= true then
        self.share = alternate
        if self.share == nil then
            self.share = gauge
        end
    else
        self.share = nil
    end
    if busy == true then
        self.busy = true
    end
end
function Pack:hides(wield)
    if self.covered ~= nil then
        return self.covered
    end
    if self.linked == nil or wield == nil then
        return false
    end
    if self.judge:call(self.linked_ammo_target, 0, self.out, wield) == nil then
        return false
    end
    return tonumber(self.out[0]) == self.linked
end
return Pack
end
modules["game.panel"] = function(require)
local Panel = {}
Panel.__index = Panel
local function flag(value)
    return value ~= nil and value ~= 0
end
local STYLE_WIDGETS = { "magazine", "throwable", "reserve", "stims" }
function Panel.new(read, n)
    local style = {}
    for _, widget in ipairs({ n.self_magazine_fill, n.self_throwable_text, n.self_reserve_text, n.self_stims_text }) do
        for index = 0, 2 do
            style[#style + 1] = { widget + n.widget_local_colour + index * 4, "f32" }
        end
    end
    style[#style + 1] = { n.self_throwable_text + n.widget_local_opacity, "f32" }
    style[#style + 1] = { n.self_weapon_block + n.widget_local_opacity, "f32" }
    local health_at = n.self_panel_health_bar + n.health_bar_drawn
    return setmetatable({
        read = read,
        n = n,
        ammunition = {},
        sample = {},
        health_at = health_at,
        health_cells = read.layout({ { health_at, "f32" }, { n.self_panel_health_danger, "u8" } }),
        supply_cells = read.layout({}),
        style_cells = read.layout(style),
        colours = { magazine = {}, throwable = {}, reserve = {}, stims = {} },
        health_values = {},
        supply_values = {},
        style_values = {},
    }, Panel)
end
function Panel:configure(values)
    local n, fields, indices = self.n, {}, {}
    local function add(name, at, form)
        fields[#fields + 1] = { at, form }
        indices[name] = #fields
    end
    if values["hud.weapon3d.stims"] == 1 then
        add("stims", n.self_panel_stims, "i32")
    end
    if values["hud.weapon3d.ammo"] == 1 or values["hud.weapon3d.arc"] == 1 then
        add("magazine_low", n.self_panel_magazine_low, "u8")
    end
    if values["hud.weapon3d.reserve"] == 1 then
        add("reserve_low", n.self_panel_reserve_low, "u8")
    end
    if values["hud.weapon3d.pack"] == 1 then
        add("pack_low", n.self_panel_pack_low, "u8")
    end
    local cells = self.read.layout(fields)
    for name, index in pairs(indices) do
        cells[name] = index
    end
    self.supply_cells = cells
end
function Panel:observe(wanted, hud_wanted)
    local read, n = self.read, self.n
    self.base, self.mission, self.ready, self.editable, self.opacity, self.dt = nil, nil, false, false, nil, nil
    self.in_mission = nil
    if wanted == false then
        return false
    end
    local game = read:module("game")
    if game == nil then
        return false
    end
    local scene = read:ptr(game + n.hud_scene_manager)
    if scene == nil then
        return false
    end
    local kind = read:value(scene + n.hud_scene, "u32")
    if kind ~= nil then
        self.in_mission = kind == n.hud_scene_mission
    end
    if not self.in_mission then
        return false
    end
    local manager = read:ptr(game + n.roots_hud_manager_rva)
    if manager == nil then
        return false
    end
    local mission = manager + n.hud_widgets_mission_hud
    self.mission, self.base = mission, mission + n.hud_widgets_panels_self_panel_at
    if hud_wanted == false then
        return false
    end
    local language = read:ptr(game + n.ui_language_manager)
    if language == nil or read:value(language + n.ui_language_switch, "bool") ~= false then
        return false
    end
    local first = read:value(self.base, "u32")
    self.editable = read:value(manager + n.hud_built, "bool") == true and first ~= nil and first ~= 0
    if not self.editable then
        return false
    end
    self.ready = read:value(mission + n.hud_gate_ready, "bool") == true
    self.opacity = read:value(self.base + n.widget_inherited_opacity, "f32")
    local clock = read:ptr(game + n.stratagem_slots_clock_global)
    if clock ~= nil then
        self.dt = read:value(clock + n.hud_dt_at, "f32")
    end
    return true
end
function Panel:health_colour()
    if not self.ready then
        return nil
    end
    local n = self.n
    return self.read:vector(self.base + n.self_panel_health_bar + n.health_bar_fill + n.widget_local_colour, 3)
end
function Panel:style(throwing, reserve_shown)
    if not self.ready then
        return nil
    end
    local got, style = self.read:value(self.base, self.style_cells, self.style_values), self.colours
    for slot, name in ipairs(STYLE_WIDGETS) do
        local colour, at = style[name], (slot - 1) * 3
        colour[1], colour[2], colour[3] = got[at + 1], got[at + 2], got[at + 3]
    end
    if not reserve_shown then
        style.reserve[1], style.reserve[2], style.reserve[3] = nil, nil, nil
    end
    style.number, style.opacity = style.magazine, got[14]
    if throwing then
        if got[4] ~= nil then
            style.number = style.throwable
        end
        if got[13] ~= nil then
            style.opacity = got[13]
        end
    end
    return style
end
function Panel:magazine_size()
    if self.ready then
        return self.read:vector(self.base + self.n.panel_magazine_outline + self.n.hud_widgets_size_x, 2)
    end
end
function Panel:throwable_icon()
    if not self.ready then
        return nil
    end
    local read, n, base = self.read, self.n, self.base
    return read:value(base + n.self_panel_throwable_picture, "hex64"),
        read:vector(base + n.self_panel_throwable_icon + n.hud_widgets_size_x, 2)
end
function Panel:health()
    if self.ready then
        return self.read:value(self.base + self.health_at, "f32")
    end
end
function Panel:stamina()
    if not self.ready then
        return nil
    end
    return self.read:value(self.mission + self.n.hud_widgets_stamina_panel_at + self.n.stamina_panel_share, "f32")
end
function Panel:events(values, world_ready, count_2d)
    if not self.ready then
        return nil
    end
    local read, n, base, sample, ammo = self.read, self.n, self.base, self.sample, self.ammunition
    local number = world_ready and values["hud.weapon3d.ammo"] == 1
    local arc = world_ready and values["hud.weapon3d.arc"] == 1
    local reserve = world_ready and values["hud.weapon3d.reserve"] == 1
    local throwables = world_ready and values["hud.weapon3d.throwables"] == 1
    local pack = world_ready and values["hud.weapon3d.pack"] == 1
    sample.health, sample.danger, sample.stamina, sample.worn = nil, nil, nil, nil
    sample.gauge, sample.spare, sample.pack_low, sample.ammo = nil, nil, nil, ammo
    ammo.throwing, ammo.hidden, ammo.drawn, ammo.count, ammo.text = nil, nil, nil, nil, nil
    ammo.empty, ammo.reserve, ammo.throwables, ammo.throwables_unheld = nil, nil, nil, nil
    ammo.stims, ammo.magazine_low, ammo.reserve_low = nil, nil, nil
    if number or arc or reserve or throwables then
        ammo.throwing = read:value(base + n.hud_self_last_slot, "u32") == n.throwable_slot
    end
    local shown
    if number or arc or count_2d then
        local state = read:value(base + n.hud_weapon_ammo_state, "i32")
        shown = state ~= nil and state ~= n.hud_ammo_none_state
        ammo.hidden = state ~= nil and not shown
        if arc or (shown and (count_2d or (number and not ammo.throwing))) then
            ammo.drawn = read:value(base + n.hud_weapon_count_shown, "i32")
        end
        if shown and arc then
            ammo.empty = read:value(base + n.ammo_gauge, "f32")
        end
    end
    if (ammo.throwing and (number or arc)) or (throwables and not ammo.throwing) then
        local count = read:value(base + n.hud_self_throwables, "i32")
        if ammo.throwing then
            ammo.throwables = count
        else
            ammo.throwables_unheld = count
        end
    end
    if number then
        if shown and ammo.throwing and ammo.throwables == nil and not arc and not count_2d then
            ammo.drawn = read:value(base + n.hud_weapon_count_shown, "i32")
        end
        ammo.text = ammo.throwables
        if shown and ammo.text == nil then
            ammo.text = ammo.drawn
        end
    end
    if shown and (number or count_2d) then
        ammo.count = ammo.drawn
    end
    if reserve or pack then
        local spare = read:value(base + n.spare_widget, "bit", n.widget_shown_bit)
        sample.spare = spare ~= nil and spare ~= 0
        if reserve and sample.spare and not ammo.throwing then
            ammo.reserve = read:value(base + n.hud_weapon_reserve_shown, "u32")
        end
    end
    if world_ready and self.supply_cells.n > 0 then
        local cells = self.supply_cells
        local got = read:value(base, cells, self.supply_values)
        ammo.stims = got[cells.stims]
        if cells.magazine_low ~= nil and shown then
            ammo.magazine_low = flag(got[cells.magazine_low])
        end
        if cells.reserve_low ~= nil and sample.spare then
            ammo.reserve_low = flag(got[cells.reserve_low])
        end
        if cells.pack_low ~= nil then
            sample.pack_low = flag(got[cells.pack_low])
        end
    end
    if world_ready and values["hud.weapon3d.health"] == 1 then
        local got = read:value(base, self.health_cells, self.health_values)
        sample.health, sample.danger = got[1], flag(got[2])
    end
    if world_ready and values["hud.weapon3d.stamina"] == 1 then
        sample.stamina = self:stamina()
    end
    if pack or reserve then
        sample.gauge = read:value(base + n.self_panel_gauge_shown, "f32")
        local worn = read:value(base + n.self_panel_pack_cell, "bit", n.widget_shown_bit)
        sample.worn = worn ~= nil and worn ~= 0
    end
    return sample
end
function Panel:clock()
    if self.ready then
        return self.read:value(self.mission + self.n.hud_clock, "f32")
    end
end
function Panel:weapon_mount()
    if not self.editable then
        return nil
    end
    local row = self.base + self.n.self_weapon_widget
    local opacity = self.read:value(row + self.n.hud_widgets_shown, "f32")
    return self.base + self.n.self_weapon_block, row, opacity ~= nil and opacity > 0
end
return Panel
end
modules["game.projectile"] = function(require)
local Projectile = {}
Projectile.__index = Projectile
local function value(read, base, offset, form)
    if base ~= nil and base ~= 0 then
        return read:value(base + offset, form)
    end
end
local function key_argument(judge, key)
    if key == false then
        key = "0000000000000000"
    end
    if key ~= nil then
        return judge:uint64_of(key)
    end
end
function Projectile.new(weapon)
    local judge = weapon.judge
    return setmetatable({
        weapon = weapon,
        read = weapon.read,
        judge = judge,
        n = weapon.n,
        can_call = assert(judge:routine("can_fire")),
        open_call = assert(judge:routine("projectile_weapon_open")),
        function_call = assert(judge:routine("weapon_function_of")),
        aim_call = assert(judge:routine("weapon_aim_record_find")),
    }, Projectile)
end
function Projectile:clear()
    self.id, self.record, self.blob, self.data_index, self.can_fire, self.entity_key, self.flies =
        nil, nil, nil, nil, nil, nil, nil
    self.info, self.kind, self.speed, self.scale, self.aim = nil, nil, nil, nil, nil, nil
    self.projectile, self.aim_key, self.corrected = nil, nil, nil
end
function Projectile:information(kind)
    local read, n = self.read, self.n
    local held = self.projectile
    if held == nil or kind ~= held.kind then
        held = { kind = kind }
        self.projectile = held
        if kind ~= nil and kind > 0 then
            held.info = read:ptr(self.weapon.game + n.projectile_info_table + kind * n.projectile_info_stride)
        end
        held.impact = value(read, held.info, n.projectile_explosion_impact, "u32")
        held.expire = value(read, held.info, n.projectile_explosion_expire, "u32")
    end
    return held
end
function Projectile:details()
    local held, read, n = self.projectile, self.read, self.n
    if held.detail == nil then
        local at, v = held.info, {}
        v.mass = value(read, at, n.projectile_mass, "f32")
        v.drag = value(read, at, n.projectile_drag, "f32")
        v.gravity = value(read, at, n.projectile_gravity_scale, "f32")
        v.substeps = value(read, at, n.projectile_substeps, "u32")
        v.life = value(read, at, n.projectile_lifetime, "f32")
        v.caliber = value(read, at, n.projectile_caliber, "f32")
        v.arming = value(read, at, n.projectile_arming, "f32")
        v.flags = value(read, at, n.projectile_info_flags, "u32")
        v.filter = value(read, at, n.projectile_info_filter, "u32")
        v.explode_angle = value(read, at, n.projectile_explode_angle, "f32")
        v.ricochets = value(read, at, n.projectile_ricochets, "u32")
        v.ricochet_angle = value(read, at, n.projectile_ricochet_angle, "f32")
        v.ricochet_speed = value(read, at, n.projectile_ricochet_speed, "f32")
        v.speed = value(read, at, n.projectile_speed, "f32")
