                        out.record = record
                    end
                end
            end
        end
    end
end
function Inputs:supply(cell)
    local value = self.weapon.read:value(cell + self.weapon.n.squad_cell_share, "f32")
    if value == nil or value ~= value or value < 0 then
        return nil
    end
    return math.min(value, 1)
end
function Inputs:observe(panel, enabled, supply, avatar, player, players, dead)
    self.rows, self.view, self.textures = {}, nil, {}
    self.comms:observe(enabled and panel.editable)
    if not enabled or not panel.editable then
        return
    end
    local w, n = self.weapon, self.weapon.n
    local read = w.read
    local loadouts, beacon, history =
        w:manager(n.roster_rows_global), w:manager(n.beacon_manager), w:manager(n.stratagem_slots_global)
    local inventory
    local entries
    if beacon ~= nil then
        entries = read:ptr(beacon + n.beacon_entries)
    end
    local base = panel.mission + n.hud_widgets_panels_squad_panel_at
    local first = read:value(base, "u32")
    if first ~= nil and first ~= 0 then
        for index = 0, n.hud_squad_count - 1 do
            local at = base + n.hud_squad_first + index * n.hud_squad_stride
            local shown = read:value(at, "bit", n.widget_shown_bit)
            if shown ~= nil and shown ~= 0 then
                local death = read:value(at + n.hud_squad_death, "u32")
                local row = {
                    parent = at,
                    player = read:value(at + n.hud_squad_player, "u32"),
                    avatar = read:value(at + n.hud_squad_avatar, "u32"),
                }
                if death ~= nil then
                    row.dead = death ~= 0
                end
                self.rows[index + 1] = row
                row.edge = at + n.squad_weapon_object
                for slot = 2, 0, -1 do
                    local gear = at + n.squad_slot_base + slot * n.squad_slot_stride
                    local visible = read:value(gear, "bit", n.widget_shown_bit)
                    if visible ~= nil and visible ~= 0 then
                        row.edge = gear
                        break
                    end
                end
                if supply then
                    row.stim, row.ammo = self:supply(at + n.squad_stim_cell), self:supply(at + n.squad_weapon_object)
                end
                if supply and row.edge ~= at + n.squad_weapon_object then
                    row.pack = self:supply(at + n.squad_slot_base)
                    if inventory == nil then
                        inventory = w:manager(n.inventory_manager)
                    end
                    if
                        inventory ~= nil
                        and row.avatar ~= nil
                        and w.judge:call(self.worn_pack, inventory, w.out, row.avatar) ~= nil
                    then
                        row.pack_id = tonumber(w.out[0])
                    end
                end
                self:icon(row, loadouts)
                self:calls(row, beacon, entries, history)
            end
        end
    end
    self.view = self:subject(panel, avatar, player, players, dead)
    if self.view ~= nil then
        self:icon(self.view, loadouts)
    end
end
return Inputs
end
modules["game.stratagem_card"] = function(require)
local Card = {}
Card.__index = Card
function Card.new(ui)
    return setmetatable({ ui = ui }, Card)
end
function Card.tick_untouched(ui, name, ...)
    local random = assert(ui.read:module("game")) + ui.n.game_random
    local saved = assert(ui.read:text(random, 8))
    local okay, why = pcall(ui.call, ui, name, ...)
    ui:put(random, saved)
    if not okay then
        error(why, 0)
    end
end
local function overrun(ui, at)
    local spot = ui.read:vector(at + ui.n.stratagem_card_fill_0 + ui.n.widget_local_position, 2)
    return spot ~= nil and spot[2] > 0
end
function Card.carry(ui, to, from)
    local n = ui.n
    ui:put(
        to + n.component_card_denominator,
        overrun(ui, from) and n.component_card_span_unset
            or assert(ui.read:value(from + n.component_card_denominator, "u32"))
    )
end
function Card.rebase(ui, at, state)
    if state == ui.n.component_card_cooling and overrun(ui, at) then
        ui:put(at + ui.n.component_card_denominator, ui.n.component_card_span_unset)
    end
end
function Card.flatten(ui, at)
    local n = ui.n
    for _, offset in ipairs({
        n.stratagem_card_mask_0,
        n.stratagem_card_mask_1,
        n.stratagem_card_mask_2,
        n.stratagem_card_mask_3,
    }) do
        ui:material({ at = at + offset }, n.flat_mask_material)
    end
    for _, offset in ipairs({
        n.stratagem_card_fill_0,
        n.stratagem_card_fill_name,
        n.stratagem_card_badge_fill,
        n.stratagem_card_badge_back,
    }) do
        ui:material({ at = at + offset }, n.flat_fill_material)
    end
    ui:call(
        "picture_set",
        at + n.stratagem_card_noise,
        assert(ui:resource(n.flat_picture_material)),
        assert(ui:resource(n.stratagem_card_noise_texture)),
        0
    )
    ui:call(
        "text_font_set",
        at + n.stratagem_card_count_text,
        n.world_text_font,
        n.world_text_flat,
        n.stratagem_card_text_style,
        1,
        0
    )
    ui:call(
        "text_font_set",
        at + n.stratagem_card_uses_text,
        n.stratagem_card_uses_font,
        n.world_text_flat,
        n.stratagem_card_text_style,
        1,
        0
    )
end
function Card:create(parent, frame, layer, flat)
    local ui, n = self.ui, self.ui.n
    self.node = ui:node(n.component_card_size, self.node)
    local pair = ui:pair(0, 0)
    ui:call("component_card_create", self.node.at, pair, pair, pair, layer, 0)
    if flat then
        Card.flatten(ui, self.node.at)
    end
    ui:attach(parent, self.node)
    ui:show(self.node, false)
    self.created, self.row, self.identity, self.valid = frame, nil, nil, false
    return self.node
end
function Card:update(frame, dt, row, record, state, identity)
    local ui, n, node = self.ui, self.ui.n, self.node
    if node == nil or not node.live then
        return
    end
    if dt == nil or row == nil or record == nil or state == nil then
        ui:show(node, false)
        self.valid = false
        return
    end
    if frame == self.created then
        return
    end
    if not self.valid or self.row ~= row then
        ui:put(node.at + n.component_card_row, row)
    end
    if identity ~= nil and self.identity ~= identity then
        ui:put(node.at + n.component_card_state, 0)
    end
    ui:show(node, true)
    Card.rebase(ui, node.at, state)
    if state == n.component_card_zone0 then
        Card.tick_untouched(ui, "component_card_tick", node.at, dt, state, record)
    else
        ui:call("component_card_tick", node.at, dt, state, record)
    end
    self.row, self.identity, self.valid = row, identity, true
end
function Card:close()
    self.ui:destroy(self.node)
    self.valid = false
end
return Card
end
modules["game.stratagem_inputs"] = function(require)
local Inputs = {}
Inputs.__index = Inputs
function Inputs.new(weapon)
    return setmetatable({ weapon = weapon, read = weapon.read, n = weapon.n }, Inputs)
end
function Inputs:ball(cell)
    local weapon, n = self.weapon, self.n
    local manager = weapon:manager(n.beacon_manager)
    if manager == nil then
        return nil
    end
    return weapon:find(manager + n.beacon_map, cell, weapon.invalid_entity), manager
end
function Inputs:wrapper(panel)
    return panel.mission + self.n.hud_widgets_panels_stratagem_hud_at
end
local function find_history(self, avatar, players)
    local weapon, read, n = self.weapon, self.read, self.n
    if avatar == nil or avatar == weapon.invalid_avatar or players == nil then
        return nil
    end
    local history = weapon:manager(n.stratagem_slots_global)
    if history == nil then
        return nil
    end
    local count = read:value(history + n.player_history_count, "u32")
    local key = weapon:local_key(players)
    if count == nil or count > n.player_history_limit or key == nil then
        return nil
    end
    for index = 0, count - 1 do
        local entry = history + index * n.player_history_stride
        local current = read:value(entry, "key64")
        if current == nil then
            return nil
        end
        if current == key then
            return entry + n.player_history_data
        end
    end
end
function Inputs:history(avatar, players)
    if self.mine == nil then
        self.mine = find_history(self, avatar, players) or false
    end
    return self.mine or nil
end
function Inputs:record(avatar, players, row)
    local read, n = self.read, self.n
    if row == nil or row < 0 or row >= n.stratagem_row_cap then
        return nil
    end
    local record = self:history(avatar, players)
    if record ~= nil and read:value(record + row * n.stratagem_row_stride + n.stratagem_row_record, "u32") ~= nil then
        return record
    end
end
function Inputs:selection(panel, world, select)
    local read, n = self.read, self.n
    local wrapper = self:wrapper(panel)
    self.mode = read:value(wrapper + n.stratagem_panel_input, "u8")
    if self.mode ~= nil and self.mode > 0 then
        self.listing = true
    end
    if not select then
        return
    end
    self.showing = true
    self.group, self.original = wrapper + n.stratagem_panel_group, wrapper + n.stratagem_list
    local input = world.manager + n.stratagem_input + world.index * n.roots_avatar_manager_controller_stride
    self.input = input
    if self.listing then
        return
    end
    local matched = read:value(input + n.stratagem_input_number, "u32")
    if matched ~= nil and matched > 0 then
        self.row = read:value(input + n.stratagem_input_row, "u32")
    end
end
function Inputs:prepare(panel, world, select, list)
    self.showing, self.listing, self.player, self.mode, self.row, self.card_record = nil, nil, nil, nil, nil, nil
    self.original, self.group, self.wanted, self.input = nil, nil, nil, nil
    self.mine = nil
    if not (select or list) or not panel.editable or world.ready ~= true then
        return false
    end
    local read, n = self.read, self.n
    local wanted =
        read:value(world.manager + n.avatar_wanted_slot + world.index * n.roots_avatar_manager_controller_stride, "u32")
    self.wanted = wanted == n.stratagem_ball_slot
    if self.wanted then
        self:selection(panel, world, select)
    end
    return select == true and (not self.wanted or (not self.listing and self.row == nil))
end
function Inputs:observe(panel, world, player, players, cell)
    if self.wanted == nil then
        return
    end
    local read, n = self.read, self.n
    local ball, beacon
    if not self.wanted then
        ball, beacon = self:ball(cell)
        if ball == nil then
            return
        end
        self:selection(panel, world, true)
    end
    if self.listing then
        self.player = player
        return
    end
    if self.row == nil then
        if beacon == nil then
            ball, beacon = self:ball(cell)
        end
        if ball ~= nil then
            local entries = read:ptr(beacon + n.beacon_entries)
            if entries ~= nil then
                self.row = read:value(entries + ball * n.beacon_entry_size + n.beacon_row, "u32")
            end
        end
    end
    self.card_record = self:record(world.avatar, players, self.row)
end
return Inputs
end
modules["game.stratagem_list"] = function(require)
local Card = require("game.stratagem_card")
local List = {}
List.__index = List
function List.new(ui)
    return setmetatable({ ui = ui, names = {}, was = {}, faded = {} }, List)
end
function List:create(parent, frame)
    local ui, n = self.ui, self.ui.n
    local size = n.stratagem_list + n.stratagem_list_first_row + n.stratagem_list_row_size * n.stratagem_list_slots
    self.node = ui:node(size, self.node)
    self.target = self.node.owner + n.stratagem_list
    ui:call(
        "stratagem_panel_create",
        self.node.owner,
        ui:pair(0, 0),
        ui:pair(0.5, 1),
        ui:pair(0, 0),
        ui:pair(0.635, 0.871)
    )
    ui:scale(self.node, 0.6, 0.6)
    ui:call("widget_opacity_set", self.node.owner + n.stratagem_panel_root, n.stratagem_list_opacity[1])
    ui:call("widget_pivot_set", self.target, ui:pair(0, 0))
    ui:call("widget_opacity_set", self.node.owner + n.stratagem_panel_bracket, 0)
    local shadow, offset = n.stratagem_arrow_shadow_color, n.shadow_offset
    for index = 0, n.stratagem_list_rows - 1 do
        local row = self.target + n.stratagem_list_first_row + index * n.stratagem_list_row_size
        Card.flatten(ui, row + n.stratagem_row_card)
        ui:material({ at = row + n.stratagem_row_blur + n.blur_picture }, n.flat_blur_material)
        local name = row + n.stratagem_row_name
        self.names[index + 1] = name
        ui:call("text_font_set", name, n.stratagem_row_name_font, n.world_text_flat, n.stratagem_row_text_style, 1, 0)
        ui:call(
            "text_font_set",
            row + n.stratagem_row_state,
            n.stratagem_row_state_font,
            n.world_text_flat,
            n.stratagem_row_text_style,
            1,
            0
        )
        for arrow = 0, n.stratagem_row_arrows - 1 do
            local picture = { at = row + n.stratagem_row_arrow + arrow * n.stratagem_row_arrow_size }
            ui:call(
                "picture_set",
                picture.at,
                assert(ui:resource(n.choice_arrow_material)),
                assert(ui:resource(n.choice_arrow_picture)),
                0
            )
            ui:material_four(picture, n.shadow_color_key, shadow[1], shadow[2], shadow[3], shadow[4])
            ui:material_pair(picture, n.shadow_offset_key, offset[1], offset[2])
        end
    end
    ui:attach(parent, self.node)
    ui:show(self.node, false)
    self.created, self.valid = frame, false
    return self.node
end
function List:update(frame, dt, player, mode, original, dim, unready)
    local ui, n, node, faded = self.ui, self.ui.n, self.node, self.faded
    if node == nil or not node.live or frame == self.created then
        return
    end
    if mode ~= nil then
        ui:call("stratagem_list_input", self.target, mode)
        if mode == 0 then
            for at in pairs(faded) do
                faded[at] = nil
            end
        end
    end
    if dt == nil or player == nil or mode == nil then
        ui:show(node, false)
        self.valid = false
        return
    end
    ui:show(node, true)
    local opening, was = not self.valid and original ~= nil, self.was
    for at in pairs(faded) do
        if ui.read:value(at + n.component_card_state, "u32") == n.component_card_ready then
            ui:call("widget_opacity_set", at, n.stratagem_card_restore[1])
            faded[at] = nil
        end
    end
    if opening then
        for index = 0, n.stratagem_list_rows - 1 do
            local offset = n.stratagem_list_first_row + n.stratagem_row_card + index * n.stratagem_list_row_size
            was[index + 1] = ui.read:value(self.target + offset + n.component_card_state, "u32")
        end
    end
    Card.tick_untouched(ui, "stratagem_list_tick", self.target, dt, player, n.stratagem_open_full[1])
    if opening then
        for index = 0, n.stratagem_list_rows - 1 do
            local offset = n.stratagem_list_first_row + n.stratagem_row_card + index * n.stratagem_list_row_size
            local state = ui.read:value(original + offset + n.component_card_state, "u32")
            if state == n.component_card_calling or state == n.component_card_cooling then
                if state ~= was[index + 1] then
                    Card.carry(ui, self.target + offset, original + offset)
                else
                    Card.rebase(ui, self.target + offset, state)
