local ratio = require("game.ratio")
local Throwable = {}
Throwable.__index = Throwable
function Throwable.new(weapon)
    return setmetatable({
        weapon = weapon,
        read = weapon.read,
        judge = weapon.judge,
        n = weapon.n,
