function Ui:scale(node, x, y)
    put_pair(self, node, "widget_scale_set", x, y)
end
function Ui:anchor(node, x, y)
    put_pair(self, node, "widget_anchor_set", x, y)
end
function Ui:pivot(node, x, y)
    put_pair(self, node, "widget_pivot_set", x, y)
