function Line:show(shown)
    if self.root ~= nil and self.root.live then
        self.ui:show(self.root, shown)
    end
    if self.icons ~= nil and self.icons.live then
        self.ui:show(self.icons, shown)
    end
    if not shown then
        self.function_cell:update(0)
        self.fire_cell:update(0)
        self.zero_cell:update(0)
    end
end
function Line:update(frame, values)
    self.function_cell:update(frame, unpack(values[1], 1, 3))
    self.fire_cell:update(frame, unpack(values[2], 1, 3))
    self.zero_cell:update(frame, unpack(values[3], 1, 3))
    if self.icons ~= nil and self.icons.live then
        self.icons_layout:place()
    end
end
function Line:extend(row, block)
    local ui, read, n = self.ui, self.ui.read, self.ui.n
    if self.line == nil or not self.line.live then
        return false
    end
    self.layout:place()
    if read:ptr(block + n.widget_parent) ~= row or read:ptr(self.root.at + n.widget_parent) ~= block then
        error("weapon-line-parent", 0)
    end
    local position = read:vector(block + n.widget_local_position, 2)
    local tail = read:vector(block + n.widget_local_size, 2)
    local factor = read:vector(block + n.widget_size_factor, 2)
    local content = read:vector(self.line.at + n.widget_local_size, 2)
    local parent = read:vector(row + n.widget_local_size, 2)
    local line_offset = read:vector(self.line.at + n.widget_local_position, 2)
    local root_offset = read:vector(self.root.at + n.widget_local_position, 2)
    if
        position == nil
        or tail == nil
        or factor == nil
        or content == nil
        or parent == nil
        or line_offset == nil
        or root_offset == nil
    then
        return false
    end
    if content[1] <= 0 then
        return false
    end
    local right = content[1] + line_offset[1] + root_offset[1] + tail[1]
    local width = math.ceil(position[1] + right * factor[1]) + 10
    if parent[1] ~= width then
        ui:call("widget_size_set", row, ui:pair(width, parent[2]))
    end
    return true
end
function Line:reset(panel, requested)
    if panel == nil then
        return nil
    end
    local ui, n = self.ui, self.ui.n
    local before = ui.read:value(panel + n.self_weapon_layout_request, "u8")
    if before == nil then
        return nil
    end
    if requested then
        return before == 0 and "cleared" or "requested"
    end
    if before ~= n.self_layout_request_on then
        ui:put(panel + n.self_weapon_layout_request, n.self_layout_request_on, 1)
    end
    return "requested"
end
function Line:close()
    self.ui:destroy(self.root)
    self.ui:destroy(self.icons)
    self.ui:destroy(self.line)
    self.ui:destroy(self.text)
    self.function_cell:close()
    self.fire_cell:close()
    self.zero_cell:close()
    self.parent, self.row = nil, nil
end
return Line
end
modules["game.weapon_options"] = function(require)
local Options = {}
Options.__index = Options
function Options.new(weapon)
    local judge, n = weapon.judge, weapon.n
    return setmetatable({
        weapon = weapon,
        judge = judge,
        n = n,
        value_call = assert(judge:routine("axis_value")),
        candidate_call = assert(judge:routine("axis_candidate")),
        out = assert(judge:buffer("uint64_t", 1)),
        slots = {
            { offset = n.weapon_data_r1_axis_1, slot = n.option_slot_1, limit = n.axis_rows_1 },
            { offset = n.weapon_data_r1_axis_2, slot = n.option_slot_2, limit = n.axis_rows_2 },
            { offset = n.weapon_data_r1_axis_3, slot = n.option_slot_3, limit = n.axis_rows_3 },
        },
    }, Options)
end
function Options:clear()
    self.manager, self.id, self.row, self.index = nil, nil, nil, nil
    for _, slot in ipairs(self.slots) do
        slot.key, slot.output = nil, nil
    end
end
function Options:observe(id)
    local weapon, n = self.weapon, self.n
    local manager = weapon:manager(n.weapon_data_manager)
    local index
    if manager ~= nil then
        index = weapon:find(manager + n.weapon_data_map, id, weapon.invalid_entity)
    end
    local rows
    if index ~= nil then
        rows = weapon.read:ptr(manager + n.weapon_data_r1_at)
    end
    if rows == nil then
        self:clear()
        self.manager = manager
        return
    end
    self.manager, self.id, self.row, self.index = manager, id, rows + index * n.weapon_data_r1_stride, index
end
function Options:mode()
    if self.row == nil then
        return nil
    end
    local read, n = self.weapon.read, self.n
    local rows = read:ptr(self.manager + n.weapon_data_at)
    local mode
    if rows ~= nil then
        mode = read:value(rows + self.index * n.weapon_data_stride + n.weapon_data_raw_mode, "u32")
    end
    return mode, read:value(self.row + n.weapon_data_fire_count, "u32")
end
function Options:search(slot, axis, value, same)
    for index = 0, slot.limit - 1 do
        self.out[0] = 0
        local candidate = self.judge:call(self.candidate_call, self.manager, self.id, axis, index, self.out)
        if candidate == nil then
            return nil, false
        end
        if candidate == self.n.candidate_none then
            break
        end
        if (candidate == value) == same then
            return self.judge:hex64(self.out[0]), true
        end
    end
    return nil, true
end
function Options:left_axis(axis, value, equipment)
    if value ~= nil and value > 0 then
        return axis
    end
    local record
    if equipment ~= nil then
        record = equipment.record
    else
        record = self.weapon:record(self.id)
    end
    if record ~= nil then
        local manager = self.weapon:manager(self.n.customization_manager)
        local row
        if manager ~= nil then
            row = self.weapon:find(manager + self.n.customization_map, self.id, self.weapon.invalid_entity)
        end
        local rows
        if row ~= nil then
            rows = self.weapon.read:ptr(manager + self.n.customization_rows)
        end
        local unit
        if rows ~= nil then
            unit = self.weapon.read:value(rows + row * self.n.customization_row_stride, "u32")
        end
        if unit ~= nil and unit ~= self.n.unit_none then
            return nil
        end
    end
    return axis
end
function Options:sample(index, equipment)
    local slot = self.slots[index]
    if self.row == nil then
        return nil
    end
    local axis = self.weapon.read:value(self.row + slot.offset, "u32")
    local value
    if axis ~= nil then
        value = self.judge:call(self.value_call, self.manager, self.id, slot.slot)
    end
    if axis == nil or value == nil then
        slot.key, slot.output = nil, nil
        if index == 1 then
            axis = self:left_axis(axis, value, equipment)
        end
        return axis, value, nil
    end
    local key = slot.key
    if key == nil or key.manager ~= self.manager or key.id ~= self.id or key.axis ~= axis or key.value ~= value then
        local other, other_ok = self:search(slot, axis, value, false)
        local output, output_ok
        if other ~= nil then
            output, output_ok = self:search(slot, axis, value, true)
        end
        slot.key = nil
        if other_ok and (other == nil or output_ok) then
            slot.key = { manager = self.manager, id = self.id, axis = axis, value = value }
        end
        slot.output = output
    end
    if index == 1 then
        axis = self:left_axis(axis, value, equipment)
    end
    return axis, value, slot.output
end
return Options
end
modules["game.weapon_panel"] = function(require)
local Gauge = require("game.gauge")
local Layout = require("game.layout")
local OptionCell = require("game.option_cell")
local Resources = require("game.resources")
local Panel = {}
Panel.__index = Panel
local WHITE = { 1, 1, 1 }
local DIRECTIONS = { { 1, 0 }, { -1, 0 }, { 0, 1 }, { 0, -1 } }
function Panel.new(ui)
    local cyan = ui.n.hud_cyan_argb
    return setmetatable({
        ui = ui,
        gauge = Gauge.new(ui, false, 1),
        nodes = {},
        layouts = {},
        stim_size = { ui.n.self_stim_icon_width, ui.n.self_stim_icon_height },
        cyan = { cyan[2], cyan[3], cyan[4] },
        size = { 0, 0 },
        function_cell = OptionCell.new(ui),
        fire_cell = OptionCell.new(ui),
        zero_cell = OptionCell.new(ui),
    }, Panel)
end
function Panel:layout(name, node, kind, parent, gap, parent_kind, padding)
    local layout = self.layouts[name]
    if layout == nil then
        layout = Layout.new(self.ui)
        self.layouts[name] = layout
    end
    layout:create(node, kind, gap, parent_kind, padding)
    if parent ~= nil then
        self.layouts[parent]:add(layout)
    end
    return layout
end
function Panel:frame(name, parent)
    local node = self.ui:frame(self.nodes[name])
    self.nodes[name] = node
    self.ui:size(node, 0, 0)
    self.ui:attach(parent, node)
    return node
end
function Panel:text(name, parent, height)
    local ui, n = self.ui, self.ui.n
    local node = ui:text_node(n.world_text_font, n.world_text_flat, n.world_text_style, height, self.nodes[name], true)
    self.nodes[name] = node
    ui:material_scalar(node, n.outer_outline_distance_key, 2)
    ui:layer(node, n.hud_text_layer)
    ui:colour(node, 1, 1, 1)
    ui:attach(parent, node)
    return node
end
function Panel:image(name, parent, centred)
    local ui, node = self.ui, self.ui:image_node(self.nodes[name])
    self.nodes[name] = node
    ui:layer(node, ui.n.hud_text_layer)
    ui:colour(node, 1, 1, 1)
    if centred then
        ui:anchor(node, 0.5, 0.5)
        ui:pivot(node, 0.5, 0.5)
    end
    ui:attach(parent, node)
    return node
end
function Panel:create(parent, frame, values)
    local ui, n, gauge = self.ui, self.ui.n, self.gauge
    gauge:create(parent)
    ui:context(parent, function()
        local column = self:frame("column", gauge.root.at)
        ui:anchor(column, 0.5, 0.5)
        ui:pivot(column, 0.5, 0.5)
        self:layout("column", column, n.layout_down, nil, nil, nil, 3)
        local ammo = self:frame("ammo_row", column.at)
        ui:show(ammo, values["hud.weapon3d.functions"] == 1 or values["hud.weapon3d.ammo"] == 1)
        self:layout("ammo_row", ammo, n.layout_right, "column", 6, n.layout_down)
        if values["hud.weapon3d.functions"] == 1 then
            local cell = self.function_cell:create(ammo.at, frame)
            local scale = values["hud.weapon3d.icon_size"]
            ui:scale(cell, scale, scale)
            self:layout("function", cell, 0, "ammo_row", 3, n.layout_right)
        end
        if values["hud.weapon3d.ammo"] == 1 then
            self:layout(
                "ammo",
                self:text("ammo", ammo.at, values["hud.weapon3d.ammo_text_size"]),
                0,
                "ammo_row",
                3,
                n.layout_right
            )
        end
        local row = self:frame("reserve_row", column.at)
        self:layout("reserve_row", row, n.layout_right, "column", 6, n.layout_down)
        local scale, count = values["hud.weapon3d.reserve_icon_size"], values["hud.weapon3d.count_text_size"]
        if values["hud.weapon3d.reserve"] == 1 then
            local magazine = self:frame("magazine", row.at)
            ui:scale(magazine, scale, scale)
            self:layout("magazine", magazine, 0, "reserve_row", 3, n.layout_right)
            self:image("outline", magazine.at, true)
            self:image("fill", magazine.at, true)
            self:layout("reserve", self:text("reserve", row.at, count), 0, "reserve_row", 3, n.layout_right)
        end
        if values["hud.weapon3d.throwables"] == 1 then
            local cell = self:frame("throwables", row.at)
            self:layout("throwables", cell, n.layout_right, "reserve_row", 3, n.layout_right)
            local icon = self:image("throwable_icon", cell.at)
            ui:scale(icon, scale, scale)
            self:layout("throwable_icon", icon, 0, "throwables", 2, n.layout_right)
            self:layout(
                "throwable_count",
                self:text("throwable_count", cell.at, count),
                0,
                "throwables",
                2,
                n.layout_right
            )
        end
        if values["hud.weapon3d.stims"] == 1 then
            local cell = self:frame("stims", row.at)
            self:layout("stims", cell, n.layout_right, "reserve_row", 3, n.layout_right)
            local icon = self:frame("stim_icon", cell.at)
            ui:size(icon, n.self_stim_icon_height, n.self_stim_icon_width)
            scale = values["hud.weapon3d.stim_icon_size"]
            ui:scale(icon, scale, scale)
            self:layout("stim_icon", icon, 0, "stims", 2, n.layout_right)
            local picture = self:image("stim_picture", icon.at, true)
            ui:size(picture, n.self_stim_icon_width, n.self_stim_icon_height)
            ui:rotation(picture, 90)
            self:layout("stim_count", self:text("stim_count", cell.at, count), 0, "stims", 2, n.layout_right)
        end
        local side = self:frame("options", gauge.arc.at)
        local toward = DIRECTIONS[values["hud.weapon3d.layout"] + 1]
        local kind = toward[1] ~= 0 and n.layout_down or n.layout_right
        ui:anchor(side, 0.5, 0.5)
        ui:pivot(side, 0.5 - toward[1] / 2, 0.5 - toward[2] / 2)
        ui:position(side, toward[1] * 48, toward[2] * 48)
        self:layout("options", side, kind)
        scale = values["hud.weapon3d.mode_icon_size"]
        if values["hud.weapon3d.fire_mode"] == 1 then
            local cell = self.fire_cell:create(side.at, frame)
            ui:scale(cell, scale, scale)
            self:layout("fire", cell, 0, "options", 8, kind)
        end
        if values["hud.weapon3d.zeroing"] == 1 then
            local cell = self.zero_cell:create(side.at, frame)
            ui:scale(cell, scale, scale)
            self:layout("zero", cell, 0, "options", 8, kind)
        end
        if values["hud.weapon3d.arc"] == 1 then
            for _, name in ipairs({ "progress", "cycle", "charge", "ready" }) do
                local node = ui:image_node(self.nodes[name])
                self.nodes[name] = node
                node.gauge_value = nil
                ui:size(node, 96, 96)
                ui:anchor(node, 0.5, 0.5)
                ui:pivot(node, 0.5, 0.5)
                ui:material(node, Resources.outer_fill)
                ui:layer(node, name == "ready" and n.hud_text_layer or n.crosshair_fill_layer)
                ui:attach(gauge.arc.at, node)
            end
        end
    end)
    self.parent, self.values, self.filled, self.sample = parent, values, false, nil
    self.size[1], self.size[2] = 0, 0
    gauge:shape(values["hud.weapon3d.layout"], values["hud.weapon3d.gauge_angle"])
end
function Panel:picture(name, hash, size)
    local ui, node, n = self.ui, self.nodes[name], self.ui.n
    if node == nil or not node.live then
        return
    end
    if size == nil then
        hash = nil
    end
    ui:image(node, hash, n.flat_ammo_icon_material)
    if hash == nil then
        return
    end
    ui:size(node, size[1], size[2])
    ui:material_four(node, n.shadow_color_key, 0.6, 0, 0, 0)
    ui:material_pair(node, n.shadow_offset_key, n.shadow_offset[1], n.shadow_offset[2])
end
local function tint(ui, node, colour)
    if colour ~= nil and colour[1] ~= nil then
        ui:colour(node, colour[1], colour[2], colour[3])
        return
    end
    local normal = ui.n.self_panel_normal_colour
    ui:colour(node, normal[2], normal[3], normal[4])
end
function Panel:put(frame, sample)
    local ui, n, nodes, gauge, style = self.ui, self.ui.n, self.nodes, self.gauge, sample.style
    ui:show(nodes.options, sample.wielded == true)
    if nodes.ammo ~= nil and nodes.ammo.live then
        ui:text(nodes.ammo, sample.ammo)
        if style ~= nil then
            tint(ui, nodes.ammo, style.number)
            if style.opacity ~= nil then
                ui:opacity(nodes.ammo, style.opacity)
            end
        end
    end
    if nodes.reserve ~= nil and nodes.reserve.live then
        ui:text(nodes.reserve, sample.reserve)
        if style ~= nil then
            tint(ui, nodes.reserve, style.reserve)
        end
        ui:show(nodes.magazine, sample.reserve ~= nil and sample.outline ~= nil and sample.magazine_size ~= nil)
        if sample.magazine_size ~= nil then
            ui:size(nodes.magazine, sample.magazine_size[1], sample.magazine_size[2])
        end
        local outline, fill
        if sample.reserve ~= nil then
            outline = sample.outline
            if sample.reserve > 0 then
                fill = sample.fill
            end
        end
        self:picture("outline", outline, sample.magazine_size)
        self:picture("fill", fill, sample.magazine_size)
    end
    if nodes.throwables ~= nil and nodes.throwables.live then
        ui:show(nodes.throwables, sample.throwables ~= nil)
        ui:text(nodes.throwable_count, sample.throwables)
        if style ~= nil then
            tint(ui, nodes.throwable_count, style.throwable)
        end
        self:picture("throwable_icon", sample.throwable_icon, sample.throwable_size)
    end
    if nodes.stims ~= nil and nodes.stims.live then
        ui:show(nodes.stims, sample.stims ~= nil)
        ui:text(nodes.stim_count, sample.stims)
        if style ~= nil then
            tint(ui, nodes.stim_count, style.stims)
        end
        self:picture("stim_picture", n.stim_icon_material, self.stim_size)
    end
    local arc = self.values["hud.weapon3d.arc"] == 1
    ui:show(gauge.track, arc)
    local ammo, progress, cycle, charge, ready
    if arc then
        ammo, progress, charge, ready = sample.empty, sample.progress, sample.charge, sample.ready
        if ammo ~= nil then
            ammo = 1 - ammo
        end
        if sample.cycle ~= nil then
            cycle = 1 - sample.cycle
        end
    end
    local arc_colour = style and style.magazine
    gauge:paint(gauge.fill, ammo, arc_colour)
    if arc then
        gauge:paint(nodes.progress, progress, WHITE)
        gauge:paint(nodes.cycle, cycle, WHITE)
        gauge:paint(nodes.charge, charge, arc_colour)
        gauge:paint(nodes.ready, ready, self.cyan)
    end
    self.filled, self.sample = true, sample
    self:update(frame)
end
function Panel:update(frame)
    local sample, nodes, ui = self.sample, self.nodes, self.ui
    if sample == nil then
        return
    end
    local slots, fuse = sample.slots, sample.fuse
    if fuse.seconds ~= nil then
        self.function_cell:update_fuse(frame, fuse.mode, fuse.pick, fuse.id, fuse.seconds)
    else
        self.function_cell:update(frame, unpack(slots[1], 1, sample.wielded == true and 3 or 0))
    end
    self.fire_cell:update(frame, unpack(slots[2], 1, 3))
    self.zero_cell:update(frame, unpack(slots[3], 1, 3))
    ui:shade(nodes.outline)
    ui:shade(nodes.fill)
    ui:shade(nodes.throwable_icon)
    ui:shade(nodes.stim_picture)
    self.layouts.column:place()
    self.layouts.options:place()
    local size = ui.read:vector(nodes.column.at + ui.n.widget_local_size, 2)
    self.size[1], self.size[2] = 0, 0
    if size ~= nil then
        self.size[1], self.size[2] = size[1], size[2]
    end
end
function Panel:hide()
    self.gauge:hide()
    self.filled, self.sample = false, nil
    self.function_cell:update(0)
    self.fire_cell:update(0)
    self.zero_cell:update(0)
end
function Panel:close()
    self.gauge:close()
    for _, node in pairs(self.nodes) do
        self.ui:destroy(node)
    end
    self.function_cell:close()
    self.fire_cell:close()
    self.zero_cell:close()
    self.parent, self.values, self.filled, self.sample = nil, nil, false, nil
    self.size[1], self.size[2] = 0, 0
end
return Panel
end
modules["game.world_inputs"] = function(require)
local Inputs = {}
Inputs.__index = Inputs
function Inputs.new(weapon)
    local judge = weapon.judge
    return setmetatable({
        weapon = weapon,
        read = weapon.read,
        n = weapon.n,
        judge = judge,
        dead_call = assert(judge:routine("dead_of")),
        dropping_call = assert(judge:routine("dropping_of")),
        open = assert(judge:routine("weapon_data_open")),
        node = assert(judge:routine("unit_node")),
    }, Inputs)
end
function Inputs:bit(at, index)
    if at == nil then
        return nil
    end
    local value = self.read:value(at, "bit", index)
    if value ~= nil then
        return value ~= 0
    end
end
function Inputs:scene(needed)
    self.world = nil
    if not needed then
        return
    end
    local weapon, read, n = self.weapon, self.read, self.n
    local scene = weapon:manager(n.hud_scene_manager)
    if scene ~= nil then
        self.world = read:ptr(scene + n.game_world_at)
    end
end
function Inputs:view(needed)
    self.camera, self.eye = nil, nil
    if not needed then
        return
    end
    local read, n = self.read, self.n
    local camera = self.weapon:manager(n.camera_manager)
    if camera ~= nil then
        self.eye, self.camera = read:vector(camera + n.camera_eye_at, 3), read:ptr(camera)
    end
end
function Inputs:death(avatar)
    local health = self.weapon:manager(self.n.health_manager)
    if health ~= nil then
        self.dead = self.judge:call(self.dead_call, health, avatar)
    end
end
function Inputs:observe(panel, avatar, world, shared, landing)
    local weapon, read, n = self.weapon, self.read, self.n
    self.ready, self.first_person, self.third_person, self.aiming, self.switching, self.holding =
        nil, nil, nil, nil, nil, nil
    self.throwing, self.melee, self.engaged = nil, nil, nil
    self.avatar, self.manager, self.index, self.actions = avatar, nil, nil, nil
    self.dead, self.landed = nil, nil
    if avatar == nil then
        return nil
    end
    if shared then
        self:death(avatar)
    end
    local manager, index
    if world or (landing and self.dead == false) then
        manager = weapon:manager(n.roots_avatar_manager_rva)
        if manager ~= nil then
            index = weapon:find(manager + n.roots_avatar_manager_map, avatar, weapon.invalid_player)
        end
    end
    self.manager, self.index = manager, index
    local active = false
    if world and index ~= nil then
        local controller = manager
            + n.roots_avatar_manager_controller_base
            + index * n.roots_avatar_manager_controller_stride
        active = read:value(controller + n.avatar_controller_dive_identity_offset, "u32") == avatar
        if active then
            local actions = controller + n.avatar_action_words
            self.actions = actions
            self.first_person = self:bit(actions, n.first_person_action_bit)
            if self.first_person ~= nil then
                self.third_person = not self.first_person
            end
            self.aiming = self:bit(actions, n.aim_action_bit)
            self.switching = self:bit(actions + n.switch_action_word, n.switch_action_bit)
            self.holding = self:bit(
                manager + index * n.roots_avatar_manager_controller_stride + n.throw_holding_word,
                n.throw_holding_bit
            )
            if not shared then
                self:death(avatar)
            end
        end
    end
    if self.dead == false and index ~= nil and (active or landing) then
        local dropping = self.judge:call(self.dropping_call, manager, index)
        if dropping ~= nil then
            self.landed = not dropping
        end
    end
