Instance.__index = Instance
function Instance:call(name, ...)
    return self.port:call(assert(self.port:routine(name)), ...)
end
local function pose_slot()
    return { x = { 0, 0, 0 }, y = { 0, 0, 0 }, z = { 0, 0, 0 }, o = { 0, 0, 0 } }
