    local colour_on = call_colour ~= nil and values["hud.call_colour"] == 1
    local hud_wanted = ammo
        or functions
        or fire_mode
        or zeroing
        or world_on
        or trajectory_on
        or attack_on
        or delivery_on
        or squad_on
        or pulse_on
        or corpse_on
        or reinforce_on
        or colour_on
