end
function Product:after(completed)
    if self.menu == nil then
        return
    end
    self.menu:after(self.dt, completed)
    self.menu_outermost = self.menu.outermost
end
function Product:close()
    local failures = {}
    local function finish(owner, method, ...)
        if owner == nil then
            return true
        end
        local okay, why = pcall(owner[method], owner, ...)
        if not okay then
            failures[#failures + 1] = tostring(why)
        end
        return okay
    end
    finish(self.menu, "close")
    finish(self.pick, "reset")
    finish(self.reticle, "step", false, self.report)
    finish(self.addons, "close")
    finish(self.squad, "close")
    finish(self.kill_pulse, "close")
    finish(self.corpse, "close")
    finish(self.reinforce, "close")
    if finish(self.panel, "observe") then
        finish(self.weapon_hud, "close")
        finish(self.world_hud, "close")
        finish(self.call_colour, "step", false, self.panel.editable)
    end
    finish(self.trajectory, "close")
    finish(self.attack, "close")
    finish(self.ground, "close")
    finish(self.delivery, "clear")
    finish(self.distance, "close")
    finish(self.options, "clear")
    finish(self.approach, "clear")
    if #failures > 0 then
        error(table.concat(failures, "\n"), 0)
    end
end
return Product
end
    local function import(name)
        if shared ~= nil and shared[name] ~= nil then
            return shared[name]
        end
        if loaded[name] ~= nil then
            return loaded[name]
        end
        local factory = modules[name]
        if factory == nil then
            return native_require(name)
        end
        local result = factory(import)
        if result == nil then
            result = true
        end
        loaded[name] = result
        return result
    end
    return import
end)(require)

-- LLL loads this archive entry under its LuaJIT boot and starts HD2 HUD+ here, the way HUD+'s own
-- boot script (replaced by LLL's boot) did: entry.start(_G) hooks the game's global update.
local entry = import("entry")
local runtime
return {
    live_lua_api = 1,
    on_enable = function()
        if runtime == nil then
            runtime = entry.start(_G)
        end
        return true
    end,
    on_disable = function()
        if runtime ~= nil then
            runtime:stop("disabled")
        end
        runtime = nil
        return true
    end,
}
